app/lib/people-admin.server.ts.source:
// Managing who is in Carrel (Owner only): add a person, set or remove their role on a project,
// disable or re-enable them. Every change goes through here, with the Owner check inside each
// function, so the page and any later tool meet the same rule.
//
// Carrel's rows decide what a person may do once they are in. Getting in is Cloudflare Access, which
// Carrel does not manage: adding a person here does not let them past Access (people.tsx says where).

import { and, asc, eq, isNull } from "drizzle-orm";
import { drizzle } from "drizzle-orm/d1";

import { people, projectMembers, projects } from "~/db/schema";
import { agentEmail, isAgentName } from "~/lib/agent-keys.server";
import type { Viewer } from "~/lib/people.server";
import type { Role } from "~/lib/roles";

/** A refusal the Owner reads on the page: the rule said no, and nothing changed. */
export class PeopleRefusal extends Error {
  constructor(message: string) {
    super(message);
    this.name = "PeopleRefusal";
  }
}

/** Anyone but the Owner is answered as if the page did not exist. */
function requireOwner(viewer: Viewer) {
  if (!viewer.isOwner || viewer.isReviewer) throw new Response("Not found", { status: 404 });
}

export type PersonRow = {
  id: number;
  email: string;
  name: string;
  isOwner: boolean;
  isReviewer: boolean;
  disabledAt: string | null;
  roles: { projectId: number; role: Exclude<Role, "owner"> }[];
};

export type ProjectRow = { id: number; slug: string; name: string; kind: "site" | "book" | null };

export async function listPeople(db: D1Database, viewer: Viewer): Promise<{ people: PersonRow[]; projects: ProjectRow[] }> {
  requireOwner(viewer);
  const d = drizzle(db);
  const [rows, members, projectRows] = await Promise.all([
    d
      .select({ id: people.id, email: people.email, name: people.name, isOwner: people.isOwner, isReviewer: people.isReviewer, disabledAt: people.disabledAt })
      .from(people)
      .orderBy(asc(people.email))
      .all(),
    d.select().from(projectMembers).all(),
    d.select({ id: projects.id, slug: projects.slug, name: projects.name, site: projects.site, book: projects.book }).from(projects).orderBy(asc(projects.name)).all(),
  ]);
  return {
    // The Owner first: the one row nothing here can change.
    people: rows
      .map((p) => ({ ...p, roles: members.filter((m) => m.personId === p.id).map(({ projectId, role }) => ({ projectId, role })) }))
      .sort((a, b) => Number(b.isOwner) - Number(a.isOwner)),
    projects: projectRows.map(({ site, book, ...p }) => ({ ...p, kind: site ? "site" : book ? "book" : null })),
  };
}

const EMAIL = /^[^\s@'"<>]+@[^\s@'"<>]+\.[^\s@'"<>]+$/;

/**
 * Adds a person. Never an Owner: Carrel has one Owner, and this function cannot make another (the
 * database refuses a second as well). An email already in Carrel is refused rather than changed.
 */
export async function addPerson(db: D1Database, viewer: Viewer, input: { email: string; name: string; reviewer: boolean }): Promise<PersonRow> {
  requireOwner(viewer);
  const email = input.email.trim().toLowerCase();
  if (!EMAIL.test(email) || email.length > 254) throw new PeopleRefusal("That is not an email address.");
  const name = input.name.trim().slice(0, 200);
  const d = drizzle(db);
  const existing = await d.select({ id: people.id }).from(people).where(eq(people.email, email)).get();
  if (existing) throw new PeopleRefusal(`${email} is already in Carrel.`);
  const [row] = await d
    .insert(people)
    .values({ email, name, isOwner: false, isReviewer: input.reviewer })
    .returning({ id: people.id, email: people.email, name: people.name, isOwner: people.isOwner, isReviewer: people.isReviewer, disabledAt: people.disabledAt });
  return { ...row!, roles: [] };
}

/**
 * Adds a named AI agent: the person row "agent:<name>" that an AGENT_KEY_<NAME> secret resolves to at
 * the AI door. Never an Owner, never a reviewer, and it starts with no role on any project. Adding the
 * row grants nothing by itself: the key is a Worker secret the Owner sets, and the role is set below.
 */
export async function addAgent(db: D1Database, viewer: Viewer, input: { name: string; label?: string }): Promise<PersonRow> {
  requireOwner(viewer);
  const name = input.name.trim().toLowerCase();
  if (!isAgentName(name)) throw new PeopleRefusal("An agent's name is letters, digits, hyphens and underscores, up to 32, such as grok.");
  const email = agentEmail(name);
  const d = drizzle(db);
  const existing = await d.select({ id: people.id }).from(people).where(eq(people.email, email)).get();
  if (existing) throw new PeopleRefusal(`${email} is already in Carrel.`);
  const [row] = await d
    .insert(people)
    .values({ email, name: input.label?.trim().slice(0, 200) || name, isOwner: false, isReviewer: false })
    .returning({ id: people.id, email: people.email, name: people.name, isOwner: people.isOwner, isReviewer: people.isReviewer, disabledAt: people.disabledAt });
  return { ...row!, roles: [] };
}

async function target(db: D1Database, personId: number) {
  const row = await drizzle(db)
    .select({ id: people.id, email: people.email, isOwner: people.isOwner, isReviewer: people.isReviewer, disabledAt: people.disabledAt })
    .from(people)
    .where(eq(people.id, personId))
    .get();
  if (!row) throw new PeopleRefusal("No such person.");
  return row;
}

/**
 * Sets a person's role on a project, or removes it (role null). The Owner has no per-project role to
 * set: the Owner is the Owner everywhere, and cannot be demoted here. A reviewer reads and flags only,
 * so a reviewer can be a Reader and never an Editor.
 */
export async function setProjectRole(db: D1Database, viewer: Viewer, personId: number, projectId: number, role: "reader" | "editor" | null): Promise<void> {
  requireOwner(viewer);
  const person = await target(db, personId);
  if (person.isOwner) throw new PeopleRefusal("The Owner's role cannot be changed: the Owner is the Owner on every project.");
  if (role === "editor" && person.isReviewer) throw new PeopleRefusal(`${person.email} is a reviewer. Reviewers read and flag only, so they can be a Reader, never an Editor.`);
  const d = drizzle(db);
  const project = await d.select({ id: projects.id }).from(projects).where(eq(projects.id, projectId)).get();
  if (!project) throw new PeopleRefusal("No such project.");
  if (role === null) {
    await d.delete(projectMembers).where(and(eq(projectMembers.projectId, projectId), eq(projectMembers.personId, personId)));
    return;
  }
  await d
    .insert(projectMembers)
    .values({ projectId, personId, role })
    .onConflictDoUpdate({ target: [projectMembers.projectId, projectMembers.personId], set: { role } });
}

/**
 * Disables a person (they are refused at both doors at once, because every request looks the person
 * up again) or re-enables them. The Owner cannot be disabled: that would lock Carrel with no one able
 * to undo it.
 */
export async function setDisabled(db: D1Database, viewer: Viewer, personId: number, disabled: boolean, now = new Date()): Promise<void> {
  requireOwner(viewer);
  const person = await target(db, personId);
  if (person.isOwner || person.id === viewer.id) throw new PeopleRefusal("The Owner cannot be disabled.");
  await drizzle(db)
    .update(people)
    .set({ disabledAt: disabled ? now.toISOString() : null })
    .where(disabled ? and(eq(people.id, personId), isNull(people.disabledAt)) : eq(people.id, personId));
}

app/lib/social/routine.server.ts.source:
// The Claude Code routine that drafts brand posts when no session drafted them ahead (design decision
// 5, second step). Carrel only fires it: a POST to the routine's API trigger with the waiting items
// as text. The routine runs on Dustin's subscription, drafts each post in the account's voice, and
// stores it through Carrel's MCP tools; Carrel sends it later with no AI at runtime. No API key and no
// subscription token is ever stored: the trigger token reaches this one routine and can read nothing.
//
// Contract (platform.claude.com/docs/en/api/claude-code/routines-fire, 2026-09-27): POST the fire URL
// with `Authorization: Bearer <token>` and `anthropic-version: 2023-06-01`, body `{ "text": ... }` of
// at most 65,536 characters; 200 returns the session; 429 is the hourly limit, with Retry-After.

type Fetch = typeof fetch;

const FIRE_URL = /^https:\/\/api\.anthropic\.com\/v1\/claude_code\/routines\/trig_[A-Za-z0-9_-]+\/fire$/;
const MAX_TEXT = 65_536;

export type RoutineConfig = { url: string; token: string };

export function routineConfig(env: Env): RoutineConfig | { missing: string } {
  const url = env.SOCIAL_ROUTINE_URL?.trim() ?? "";
  const token = env.SOCIAL_ROUTINE_TOKEN?.trim() ?? "";
  if (!url || !token) return { missing: "SOCIAL_ROUTINE_URL and SOCIAL_ROUTINE_TOKEN are not both set." };
  if (!FIRE_URL.test(url)) return { missing: "SOCIAL_ROUTINE_URL is not a routine's /fire URL (https://api.anthropic.com/v1/claude_code/routines/trig_.../fire)." };
  return { url, token };
}

export type FireResult =
  | { ok: true; sessionUrl: string }
  /** Try again later: the hourly limit, or the service briefly down. */
  | { ok: false; retry: true; error: string }
  /** Will not work until something changes: bad token, paused routine, no access. */
  | { ok: false; retry: false; error: string };

export async function fireRoutine(config: RoutineConfig, text: string, fetcher: Fetch = fetch): Promise<FireResult> {
  let res: Response;
  try {
    res = await fetcher(config.url, {
      method: "POST",
      headers: { Authorization: `Bearer ${config.token}`, "anthropic-version": "2023-06-01", "Content-Type": "application/json" },
      body: JSON.stringify({ text: text.slice(0, MAX_TEXT) }),
    });
  } catch (error) {
    return { ok: false, retry: true, error: `The routine could not be reached: ${error instanceof Error ? error.message : String(error)}` };
  }
  if (res.ok) {
    const body = (await res.json().catch(() => ({}))) as { claude_code_session_url?: string };
    return { ok: true, sessionUrl: body.claude_code_session_url ?? "" };
  }
  const body = (await res.json().catch(() => ({}))) as { error?: { type?: string; message?: string } };
  const error = `${res.status} ${body.error?.type ?? ""}${body.error?.message ? `: ${body.error.message}` : ""}`.trim();
  if (res.status === 429 || res.status >= 500) return { ok: false, retry: true, error };
  return { ok: false, retry: false, error };
}

/** What the routine is told: the items waiting, per account, and how to store a draft for each. */
export function routinePrompt(items: { eventId: number; account: string; platform: string; voiceGuide: string; title: string; url: string; summary: string }[]): string {
  const lines = [
    "Draft one social post for each item below, in that account's voice, and store each with Carrel's draft_social_post tool (event id, text). Do not post anything and do not reply to anyone.",
    "Rules: the post announces the item and links it; plain, direct sentences; no AI-writing tells; no em dashes; nothing the item does not say.",
    "",
  ];
  for (const i of items) {
    lines.push(`- event ${i.eventId} for ${i.account} (${i.platform}): "${i.title}" ${i.url}`);
    if (i.summary) lines.push(`  Dustin's summary: ${i.summary}`);
    if (i.voiceGuide) lines.push(`  Voice: ${i.voiceGuide}`);
  }
  return lines.join("\n");
}

