// Legal pages: shared sections written into each site's page, the fields they take, the date stamped
// on an Owner publish of a changed text, and the page the site's data license names that Carrel never
// takes down or moves. The write tests run Carrel's real code against site-api's reference site.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it } from "vitest";

import { writeToSite } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { readFields, splitSource } from "~/lib/frontmatter";
import { expandShared, legalTypeOf, prepareLegalWrite, sectionsUsed, type SharedSection } from "~/lib/legal";
import { deleteSection, listSections, saveSection } from "~/lib/legal.server";
import { requireSiteProject } from "~/lib/projects.server";
import { siteEntry } from "~/lib/sites.server";
import { action as legalAction, loader as legalLoader } from "~/routes/legal";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";

const SECTIONS: SharedSection[] = [
  { key: "hosting", title: "Hosting", body: "{{site_name}} runs on Cloudflare. Questions go to {{contact}}." },
  { key: "analytics", title: "Analytics", body: "Cloudflare Web Analytics counts visits without tracking cookies." },
];

const FRONT = ["---", "path: /privacy", 'title: "Privacy"', "legal_type: privacy", 'site_name: "dustinedwards.info"', 'contact: "hello@example.test"', "---", ""].join("\n");

describe("expandShared", () => {
  it("writes each section between its markers with the page's fields filled in", () => {
    const out = expandShared("Intro.\n\n<!-- shared:hosting -->\n", SECTIONS, { site_name: "dustinedwards.info", contact: "hello@example.test" });
    expect(out.text).toBe(
      "Intro.\n\n<!-- shared:hosting -->\ndustinedwards.info runs on Cloudflare. Questions go to hello@example.test.\n<!-- /shared:hosting -->\n",
    );
    expect(out.unknownSections).toEqual([]);
    expect(out.missingFields).toEqual([]);
  });

  it("gives the same text when run again, so a page is expanded on every write", () => {
    const values = { site_name: "A", contact: "b@example.test" };
    const once = expandShared("<!-- shared:hosting -->\n\n<!-- shared:analytics -->\n", SECTIONS, values).text;
    expect(expandShared(once, SECTIONS, values).text).toBe(once);
    expect(sectionsUsed(once)).toEqual(["hosting", "analytics"]);
  });

  it("replaces text a person typed inside the markers, since the section is the source", () => {
    const out = expandShared("<!-- shared:analytics -->\nold wording\n<!-- /shared:analytics -->", SECTIONS, {});
    expect(out.text).not.toContain("old wording");
  });

  it("names an unknown section and a missing field, and leaves both as written", () => {
    const out = expandShared("<!-- shared:nope -->\n<!-- shared:hosting -->", SECTIONS, { site_name: "A" });
    expect(out.unknownSections).toEqual(["nope"]);
    expect(out.missingFields).toEqual(["contact"]);
    expect(out.text).toContain("<!-- shared:nope -->");
    expect(out.text).toContain("{{contact}}");
  });
});

describe("prepareLegalWrite", () => {
  const base = { sections: SECTIONS, today: "2026-10-06" };

  it("stamps last_updated when the Owner publishes a changed text", () => {
    const result = prepareLegalWrite({ ...base, source: `${FRONT}New.\n`, stored: `${FRONT}Old.\n`, storedPublic: true, public: true });
    expect(result.ok && readFields(splitSource(result.source).front).last_updated).toBe("2026-10-06");
  });

  it("leaves the date alone when only a field changed", () => {
    const stored = `${FRONT}Same.\n`;
    const result = prepareLegalWrite({ ...base, source: stored.replace("hello@example.test", "other@example.test"), stored, storedPublic: true, public: true });
    expect(result.ok && readFields(splitSource(result.source).front).last_updated).toBe("");
  });

  it("stamps a draft that goes public even if its text was already saved", () => {
    const stored = `${FRONT}Saved earlier.\n`;
    const result = prepareLegalWrite({ ...base, source: stored, stored, storedPublic: false, public: true });
    expect(result.ok && readFields(splitSource(result.source).front).last_updated).toBe("2026-10-06");
  });

  it("does not stamp a draft save, and keeps a missing field's token so no work is lost", () => {
    const source = FRONT.replace('contact: "hello@example.test"\n', "") + "<!-- shared:hosting -->\n";
    const result = prepareLegalWrite({ ...base, source, stored: null, storedPublic: false, public: false });
    expect(result.ok && result.source).toContain("{{contact}}");
    expect(result.ok && readFields(splitSource(result.source).front).last_updated).toBe("");
  });

  it("refuses to go public with a field missing or a section unknown, and says which", () => {
    const missing = prepareLegalWrite({ ...base, source: FRONT.replace('contact: "hello@example.test"\n', "") + "<!-- shared:hosting -->\n", stored: null, storedPublic: false, public: true });
    expect(!missing.ok && missing.message).toContain("contact");
    const unknown = prepareLegalWrite({ ...base, source: `${FRONT}<!-- shared:nope -->\n`, stored: null, storedPublic: false, public: true });
    expect(!unknown.ok && unknown.message).toContain('"nope"');
  });

  it("recognises a legal page by its legal_type", () => {
    expect(legalTypeOf(FRONT)).toBe("privacy");
    expect(legalTypeOf("---\ntitle: x\n---\n")).toBeNull();
    expect(legalTypeOf("no frontmatter")).toBeNull();
  });
});

let projectId: number;
let ownerId: number;

beforeEach(async () => {
  await resetDb();
  ownerId = await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  for (const s of SECTIONS) {
    await testEnv.DB.prepare("INSERT INTO legal_sections (key, title, body, updated_by) VALUES (?, ?, ?, ?)").bind(s.key, s.title, s.body, ownerId).run();
  }
});

async function as(email: string) {
  const viewer = await viewerFor(email);
  return { viewer, project: await requireSiteProject(testEnv.DB, viewer, SLUG, "read") };
}

async function seed(site: ReturnType<typeof fakeSite>, id: string, source: string) {
  const { viewer, project } = await as("owner@test.invalid");
  const saved = await writeToSite(connectedEnv(), project, viewer, id, { action: "save", source, expectedVersion: null }, site.fetch);
  if (!saved.ok) throw new Error(saved.message);
  return saved.version;
}

const writes = (site: ReturnType<typeof fakeSite>) => site.requests.filter((r) => !r.startsWith("GET"));

describe("a legal page written to the site", () => {
  it("is published with its shared sections filled in and its date stamped, through the real write path", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.privacy", `${FRONT}Intro.\n\n<!-- shared:hosting -->\n`);
    const published = await writeToSite(connectedEnv(), project, viewer, "page.privacy", { action: "publish", expectedVersion: version }, site.fetch);
    expect(published.ok).toBe(true);
    // A publish with no text sends the stored text, so the stored text is what the draft save wrote.
    const doc = await site.adapter.content.get("page.privacy");
    expect(doc?.source).toContain("dustinedwards.info runs on Cloudflare. Questions go to hello@example.test.");
    expect(doc?.status).toBe("published");
  });

  it("stamps last_updated when the text sent with a publish changed", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.privacy", `${FRONT}Intro.\n`);
    const published = await writeToSite(connectedEnv(), project, viewer, "page.privacy", { action: "publish", expectedVersion: version, source: `${FRONT}Changed.\n` }, site.fetch);
    expect(published.ok).toBe(true);
    expect(readFields(splitSource((await site.adapter.content.get("page.privacy"))!.source).front).last_updated).toBe(new Date().toISOString().slice(0, 10));
  });

  it("is refused at publish with a field missing, and the site hears no write after the seed", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const source = FRONT.replace('contact: "hello@example.test"\n', "") + "<!-- shared:hosting -->\n";
    const version = await seed(site, "page.privacy", source);
    const before = writes(site).length;
    const published = await writeToSite(connectedEnv(), project, viewer, "page.privacy", { action: "publish", expectedVersion: version, source }, site.fetch);
    expect(published).toMatchObject({ ok: false, reason: "refused" });
    expect(writes(site).length).toBe(before);
  });

  it("is an ordinary item for an AI session: no special refusal, the same role rules", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("editor@test.invalid");
    const saved = await writeToSite(connectedEnv(), project, viewer, "page.privacy", { action: "save", source: `${FRONT}Draft text.\n`, expectedVersion: null }, site.fetch, { client: "claude" });
    expect(saved.ok).toBe(true);
  });
});

describe("PLANT: the page the site's data license names", () => {
  const TERMS = ["---", "path: /terms", 'title: "Terms"', "legal_type: terms", "---", "The terms.", ""].join("\n");

  it("cannot be unpublished through Carrel, and the site hears nothing", async () => {
    expect(siteEntry("dustinedwards").keepPublic).toContain("page.terms");
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.terms", TERMS);
    const published = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "publish", expectedVersion: version }, site.fetch);
    if (!published.ok) throw new Error(published.message);
    const before = writes(site).length;
    const result = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "unpublish", expectedVersion: published.version }, site.fetch);
    expect(result).toMatchObject({ ok: false, reason: "refused" });
    expect(writes(site).length).toBe(before);
    expect((await site.adapter.content.get("page.terms"))?.status).toBe("published");
  });

  it("can have its wording changed, but not its path", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.terms", TERMS);
    const moved = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "save", source: TERMS.replace("path: /terms", "path: /legal"), expectedVersion: version }, site.fetch);
    expect(moved).toMatchObject({ ok: false, reason: "refused" });
    expect((moved as { message: string }).message).toContain("/terms");
    const reworded = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "save", source: TERMS.replace("The terms.", "Better terms."), expectedVersion: version }, site.fetch);
    expect(reworded.ok).toBe(true);
  });

  it("is guarded by id even when its legal_type is removed", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.terms", TERMS);
    const moved = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "save", source: TERMS.replace("legal_type: terms\n", "").replace("path: /terms", "path: /legal"), expectedVersion: version }, site.fetch);
    expect(moved).toMatchObject({ ok: false, reason: "refused" });
  });
});

describe("the shared sections", () => {
  it("are changed only by the Owner", async () => {
    const editor = await as("editor@test.invalid");
    await expect(saveSection(testEnv.DB, editor.project, editor.viewer, { key: "x", title: "X", body: "Text." })).rejects.toMatchObject({ status: 403 });
    await expect(deleteSection(testEnv.DB, editor.project, "hosting")).rejects.toMatchObject({ status: 403 });
    const owner = await as("owner@test.invalid");
    expect(await saveSection(testEnv.DB, owner.project, owner.viewer, { key: "x", title: "X", body: "Text." })).toEqual({ ok: true });
    expect((await listSections(testEnv.DB)).map((s) => s.key)).toEqual(["analytics", "hosting", "x"]);
  });

  it("refuse a bad name, an empty text and a wide dash", async () => {
    const owner = await as("owner@test.invalid");
    for (const input of [
      { key: "Bad Name", title: "T", body: "B" },
      { key: "ok", title: "", body: "B" },
      { key: "ok", title: "T", body: "One — two." },
    ]) {
      expect((await saveSection(testEnv.DB, owner.project, owner.viewer, input)).ok).toBe(false);
    }
  });
});

describe("the Legal tab", () => {
  async function contextFor(email: string) {
    const context = new RouterContextProvider();
    context.set(cloudflareContext, { env: connectedEnv(), ctx: {} as ExecutionContext });
    context.set(viewerContext, await viewerFor(email));
    context.set(nonceContext, "test-nonce");
    return context;
  }

  it("lists each legal page, says which are not set up, and flags a page behind the shared text", async () => {
    const site = fakeSite();
    const realFetch = globalThis.fetch;
    globalThis.fetch = site.fetch;
    try {
      await seed(site, "page.privacy", `${FRONT}<!-- shared:analytics -->\n`);
      // The shared text changes after the page was written to the site.
      await testEnv.DB.prepare("UPDATE legal_sections SET body = ? WHERE key = ?").bind("Newer wording.", "analytics").run();
      const data = (await legalLoader({ params: { project: SLUG }, context: await contextFor("owner@test.invalid"), request: new Request("https://carrel.test/p/de-info/legal") } as never)) as {
        pages: { type: string; setUp: boolean; behind?: boolean; shared?: string[] }[];
        canManage: boolean;
        sections: unknown[];
      };
      expect(data.pages.map((p) => [p.type, p.setUp])).toEqual([["privacy", true], ["terms", false]]);
      expect(data.pages[0]).toMatchObject({ behind: true, shared: ["analytics"] });
      expect(data.canManage).toBe(true);
      expect(data.sections).toHaveLength(2);
    } finally {
      globalThis.fetch = realFetch;
    }
  });

  it("changes a section only for the Owner, through the action", async () => {
    const body = new FormData();
    body.set("intent", "save-section");
    body.set("key", "hosting");
    body.set("title", "Hosting");
    body.set("body", "New text.");
    const request = () => new Request("https://carrel.test/p/de-info/legal", { method: "POST", body });
    const ok = await legalAction({ params: { project: SLUG }, context: await contextFor("owner@test.invalid"), request: request() } as never);
    expect(ok).toMatchObject({ saved: "hosting" });
    await expect(legalAction({ params: { project: SLUG }, context: await contextFor("editor@test.invalid"), request: request() } as never)).rejects.toMatchObject({ status: 403 });
  });
});

test/media-writes.test.ts.source:
// The media library's v0.4.0 writes (job_b4acbaabf747): alt text, tags, the trash, bulk actions and
// emptying the trash, over site-api's own handler and its reference adapter. Planted: the Owner-only
// boundary (a delete, a bulk delete and an empty-trash by an Editor are refused before the site hears
// anything), a stale version (plain conflict, nothing recorded), per-file bulk reporting (a file a post
// uses is refused alone, with the post named), and a site that offers none of the writes.

import { memoryAdapter } from "@dustinedwards/site-api/testing";
import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { bulkMedia, emptyMediaTrash, listMedia, mediaMeta, parseMediaTags, restoreMedia, setMediaAlt, setMediaTags, trashMedia } from "~/lib/media.server";
import { requireSiteProject } from "~/lib/projects.server";
import { action as bulkRoute } from "~/routes/media.bulk";
import { action as mediaAction, loader as mediaLoader } from "~/routes/media";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
const PNG = Uint8Array.from(
  atob("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg=="),
  (c) => c.charCodeAt(0),
);

let site: ReturnType<typeof fakeSite<ReturnType<typeof memoryAdapter>>>;
let env: Env;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, editor, "editor");
  await share(id, reader, "reader");
  site = fakeSite();
  env = connectedEnv();
  vi.stubGlobal("fetch", site.fetch);
});

async function project(email: string) {
  return requireSiteProject(env.DB, await viewerFor(email), SLUG, "read");
}
async function actor(email: string) {
  return { viewer: await viewerFor(email) };
}
async function status(run: () => Promise<unknown>): Promise<number> {
  try {
    await run();
    return 200;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
}
async function contextFor(email: string) {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(email));
  context.set(nonceContext, "n");
  return context;
}
async function seedFile(name = "river.png") {
  const item = await site.adapter.media!.upload({ bytes: PNG, contentType: "image/png", filename: name, alt: "", changeId: `seed-${name}` });
  return { ...item, version: (await site.adapter.media!.get(item.id))!.version! };
}
async function useInPost(url: string, slug = "river-post") {
  await site.adapter.content.saveDraft(slug, { source: `---\ntitle: The river\n---\nIntro.\n\n:::figure{src="${url}" alt="The river"}\n:::\n`, expectedVersion: null, changeId: `c-${slug}` });
}
const rows = async () =>
  (await testEnv.DB.prepare("SELECT id, action, item_id AS itemId, version_before AS vb, version_after AS va, person_id AS who FROM changes ORDER BY rowid").all<{ id: string; action: string; itemId: string; vb: string | null; va: string | null; who: number }>()).results;
const sitePosts = () => site.requests.filter((r) => !r.startsWith("GET"));

async function post(path: string, fields: Record<string, string | string[]>, email: string, route: "media" | "bulk" = "media") {
  const form = new FormData();
  for (const [k, v] of Object.entries(fields)) for (const one of Array.isArray(v) ? v : [v]) form.append(k, one);
  const request = new Request(`https://carrel.test/p/${SLUG}/${path}`, { method: "POST", body: form });
  const args = { request, params: { project: SLUG }, context: await contextFor(email) } as never;
  return route === "media" ? mediaAction(args) : bulkRoute(args);
}

describe("alt text, tags, trash and restore", () => {
  it("writes each as an Editor with the version seen, and records who did it", async () => {
    const file = await seedFile();
    const editor = await project("editor@test.invalid");
    const who = await actor("editor@test.invalid");

    const alt = await setMediaAlt(env, editor, who, file.id, "The river at dusk", file.version);
    expect(alt).toMatchObject({ ok: true });
    const tags = await setMediaTags(env, editor, who, file.id, ["river", "dusk"], alt.ok ? alt.version : "");
    expect(tags.ok).toBe(true);
    const trashed = await trashMedia(env, editor, who, file.id, tags.ok ? tags.version : "");
    expect(trashed.ok).toBe(true);
    expect((await listMedia(env, editor, {})).items).toEqual([]);
    expect((await listMedia(env, editor, { trashed: "only" })).items).toMatchObject([{ id: file.id, alt: "The river at dusk", tags: ["dusk", "river"] }]);
    expect((await restoreMedia(env, editor, who, file.id, trashed.ok ? trashed.version : "")).ok).toBe(true);
    expect((await listMedia(env, editor, { tag: "dusk" })).items).toHaveLength(1);

    const editorId = (await viewerFor("editor@test.invalid")).id;
    expect((await rows()).map((r) => [r.action, r.itemId, r.who === editorId])).toEqual([
      ["media-alt", file.id, true],
      ["media-tags", file.id, true],
      ["media-trash", file.id, true],
      ["media-restore", file.id, true],
    ]);
    expect((await rows())[0]).toMatchObject({ vb: file.version, va: alt.ok ? alt.version : "x" });
  });

  it("refuses a Reader before the site hears anything, and records nothing", async () => {
    const file = await seedFile();
    const reader = await project("reader@test.invalid");
    const who = await actor("reader@test.invalid");
    site.requests.length = 0;
    expect(await status(() => setMediaAlt(env, reader, who, file.id, "x", file.version))).toBe(403);
    expect(await status(() => trashMedia(env, reader, who, file.id, file.version))).toBe(403);
    expect(await status(() => bulkMedia(env, reader, who, "trash", [{ id: file.id, version: file.version }]))).toBe(403);
    expect(sitePosts()).toEqual([]);
    expect(await rows()).toEqual([]);
  });

  it("says a stale version plainly, changes nothing and records nothing", async () => {
    const file = await seedFile();
    const editor = await project("editor@test.invalid");
    const who = await actor("editor@test.invalid");
    await setMediaAlt(env, editor, who, file.id, "first", file.version);
    const stale = await setMediaAlt(env, editor, who, file.id, "second", file.version);
    expect(stale).toMatchObject({ ok: false, conflict: true, message: expect.stringContaining("changed on the site") });
    expect((await site.adapter.media!.get(file.id))!.alt).toBe("first");
    expect(await rows()).toHaveLength(1);
  });

  it("answers the page's form with the conflict, and refuses a tag the site would not spell", async () => {
    const file = await seedFile();
    await post("media", { intent: "set-alt", id: file.id, version: file.version, alt: "first" }, "editor@test.invalid");
    expect(await post("media", { intent: "set-alt", id: file.id, version: file.version, alt: "second" }, "editor@test.invalid")).toMatchObject({ intent: "set-alt", ok: false, conflict: true });
    const fresh = (await site.adapter.media!.get(file.id))!.version!;
    expect(await post("media", { intent: "set-tags", id: file.id, version: fresh, tags: "Good Tag, bad/tag" }, "editor@test.invalid")).toMatchObject({ ok: false, message: expect.stringContaining("cannot be a tag") });
    expect(parseMediaTags("River, good tag,river")).toEqual({ ok: true, tags: ["river", "good-tag"] });
  });
});

describe("PLANT: only the Owner deletes for good or empties the trash", () => {
  it("refuses an Editor's bulk delete and empty-trash before the site hears anything, and the files stay", async () => {
    const a = await seedFile("a.png");
    const trashed = await trashMedia(env, await project("owner@test.invalid"), await actor("owner@test.invalid"), a.id, a.version);
    expect(trashed.ok).toBe(true);
    const editor = await project("editor@test.invalid");
    const who = await actor("editor@test.invalid");
    const before = await rows();
    site.requests.length = 0;

    expect(await status(() => bulkMedia(env, editor, who, "delete", [{ id: a.id }]))).toBe(403);
    expect(await status(() => emptyMediaTrash(env, editor, who))).toBe(403);
    expect(await status(() => post("media", { intent: "empty-trash", confirm: "empty" }, "editor@test.invalid"))).toBe(403);
    expect(await (await post("media/bulk", { op: "delete", item: `${a.id}\t` }, "editor@test.invalid", "bulk") as Response).status).toBe(403);
    expect(sitePosts()).toEqual([]);
    expect(site.adapter.mediaStore.has(a.id)).toBe(true);
    expect(site.adapter.deleted).toEqual([]);
    expect(await rows()).toEqual(before);
  });

  it("lets the Owner empty the trash only after confirming, then deletes what the site lets go and records each file", async () => {
    const gone = await seedFile("gone.png");
    const used = await seedFile("used.png");
    await useInPost(used.url);
    const owner = await project("owner@test.invalid");
    const who = await actor("owner@test.invalid");
    await trashMedia(env, owner, who, gone.id, gone.version);
    await trashMedia(env, owner, who, used.id, used.version);

    expect(await post("media", { intent: "empty-trash" }, "owner@test.invalid")).toEqual({ intent: "empty-trash", needsConfirm: true });
    expect(site.adapter.deleted).toEqual([]);

    const done = await post("media", { intent: "empty-trash", confirm: "empty" }, "owner@test.invalid");
    expect(done).toMatchObject({ intent: "empty-trash", ok: true, deleted: [gone.id], refused: [{ id: used.id, usedBy: [{ id: "river-post", title: "The river" }] }], more: false });
    expect(site.adapter.mediaStore.has(used.id)).toBe(true);
    const deletes = (await rows()).filter((r) => r.action === "media-delete");
    expect(deletes).toMatchObject([{ itemId: gone.id }]);
    // The site numbers files by their place in the trash it lists, refused ones included: the used file is first (newest), this one second.
    expect(deletes[0]!.id).toMatch(/-2$/);
  });
});

describe("bulk actions report each file", () => {
  it("trashes the fresh file, leaves the stale one, and records only what was done", async () => {
    const a = await seedFile("a.png");
    const b = await seedFile("b.png");
    const editor = await project("editor@test.invalid");
    const who = await actor("editor@test.invalid");
    await setMediaAlt(env, editor, who, b.id, "moved on", b.version); // b is now stale for anyone holding the old version
    const results = await bulkMedia(env, editor, who, "trash", [
      { id: a.id, version: a.version },
      { id: b.id, version: b.version },
      { id: "uploads/missing.png", version: "m99" },
    ]);
    expect(results.map((r) => [r.id, r.ok])).toEqual([[a.id, true], [b.id, false], ["uploads/missing.png", false]]);
    expect(results[1]!.message).toContain("changed on the site");
    expect((await rows()).filter((r) => r.action === "media-trash").map((r) => r.itemId)).toEqual([a.id]);
    expect((await listMedia(env, editor, {})).items.map((i) => i.id)).toEqual([b.id]);
  });

  it("names the post that blocks a bulk delete, deletes the rest, and tags in bulk", async () => {
    const free = await seedFile("free.png");
    const used = await seedFile("used.png");
    await useInPost(used.url);
    const owner = await project("owner@test.invalid");
    const who = await actor("owner@test.invalid");

    const tagged = await bulkMedia(env, owner, who, "add-tags", [{ id: free.id, version: free.version }, { id: used.id, version: used.version }], ["spring", "river"]);
    expect(tagged.every((r) => r.ok)).toBe(true);
    expect((await listMedia(env, owner, { tag: "spring" })).items).toHaveLength(2);

    const results = await bulkMedia(env, owner, who, "delete", [{ id: free.id }, { id: used.id }]);
    expect(results.find((r) => r.id === free.id)).toMatchObject({ ok: true });
    expect(results.find((r) => r.id === used.id)).toMatchObject({ ok: false, usedBy: [{ type: "post", id: "river-post", title: "The river" }] });
    expect(site.adapter.deleted).toEqual([free.id]);
    expect((await rows()).filter((r) => r.action === "media-delete").map((r) => r.itemId)).toEqual([free.id]);
  });

  it("answers the endpoint's JSON: a bad action and a bad tag are 400, and a good one lists every file", async () => {
    const a = await seedFile("a.png");
    expect(((await post("media/bulk", { op: "burn", item: a.id }, "editor@test.invalid", "bulk")) as Response).status).toBe(400);
    expect(((await post("media/bulk", { op: "add-tags", item: `${a.id}\t${a.version}`, tags: "no/good" }, "editor@test.invalid", "bulk")) as Response).status).toBe(400);
    const ok = (await post("media/bulk", { op: "trash", item: `${a.id}\t${a.version}` }, "editor@test.invalid", "bulk")) as Response;
    expect(await ok.json()).toMatchObject({ results: [{ id: a.id, ok: true }] });
  });
});

describe("a site that offers none of the writes", () => {
  beforeEach(() => {
    site = fakeSite(memoryAdapter({ mediaWrites: false }));
    vi.stubGlobal("fetch", site.fetch);
  });

  it("is told so by its meta, so the page shows no alt, tag, trash or selection tools", async () => {
    expect((await mediaMeta(env, await project("owner@test.invalid")))!.offers).toEqual({ alt: false, tags: false, trash: false });
    await seedFile();
    const data = (await mediaLoader({ request: new Request(`https://carrel.test/p/${SLUG}/media?view=trash`), params: { project: SLUG }, context: await contextFor("owner@test.invalid") } as never)) as { offers: unknown; view: string; items: unknown[] };
    expect(data.offers).toEqual({ alt: false, tags: false, trash: false });
    expect(data.view).toBe("library"); // no Trash view to open
    expect(data.items).toHaveLength(1);
  });

  it("answers a write that arrives anyway with 'not offered', not a crash", async () => {
    const file = await seedFile();
    const editor = await project("editor@test.invalid");
    expect(await trashMedia(env, editor, await actor("editor@test.invalid"), file.id, "m1")).toMatchObject({ ok: false, message: "This site does not offer that." });
    expect(await rows()).toEqual([]);
  });
});

describe("the page's loader", () => {
  it("offers the writes the site has, lists the trash on its own view, and filters by tag", async () => {
    const a = await seedFile("a.png");
    const b = await seedFile("b.png");
    const owner = await project("owner@test.invalid");
    const who = await actor("owner@test.invalid");
    await setMediaTags(env, owner, who, a.id, ["river"], a.version);
    await trashMedia(env, owner, who, b.id, b.version);
    const load = async (query: string, email = "owner@test.invalid") =>
      (await mediaLoader({ request: new Request(`https://carrel.test/p/${SLUG}/media${query}`), params: { project: SLUG }, context: await contextFor(email) } as never)) as {
        offers: unknown;
        view: string;
        items: { id: string }[];
        trashFiles: { id: string }[];
        tag: string;
        tagInvalid: boolean;
      };
    const library = await load("");
    expect(library.offers).toEqual({ alt: true, tags: true, trash: true });
    expect(library.items.map((i) => i.id)).toEqual([a.id]);
    const trash = await load("?view=trash");
    expect(trash).toMatchObject({ view: "trash", items: [{ id: b.id }], trashFiles: [{ id: b.id }] });
    expect((await load("?tag=river")).items.map((i) => i.id)).toEqual([a.id]);
    expect((await load("?tag=nothing")).items).toEqual([]);
    expect(await load("?tag=Not%20a/tag")).toMatchObject({ tag: "", tagInvalid: true });
    // An Editor sees the trash but is not handed the list that names every file for the empty-trash confirm.
    expect((await load("?view=trash", "editor@test.invalid")).trashFiles).toEqual([]);
  });
});

test/book-routes.test.ts.source:
// The book routes, driven through their loaders and actions with a real request context and the
// Worker's own GitHub client (App key and all) against the fake novels repository.

import { RouterContextProvider } from "react-router";
import { beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { clearTokenCache } from "~/lib/novels/repo.server";
import { loader as authorshipLoader } from "~/routes/book.authorship";
import { loader as chapterLoader } from "~/routes/book.chapter";
import { action as fileAction, loader as fileLoader } from "~/routes/book.file";
import { loader as newBookLoader } from "~/routes/book.new";
import { action as bookAction, loader as bookLoader } from "~/routes/book";
import { loader as exportLoader } from "~/routes/book.export";
import { loader as homeLoader } from "~/routes/home";

import { addBook, addPerson, resetDb, share, testEnv } from "./env";
import { fakeNovels, githubStyleKey } from "./novels";
import { viewerFor } from "./site";

const SLUG = "test-book";
const HEADER = "---\npov: Wade\ndate: 2024-04-12\nlocation: Harlan place\ncharacters: [Wade]\ngoal: g\nconflict: c\noutcome: o\n---\n\n";
const SCENE = "chapters/01-arrival/01-the-gate.md";

let key: string;
beforeAll(async () => {
  key = (await githubStyleKey()).pkcs1Pem;
});

let gh: ReturnType<typeof fakeNovels>;
let env: Env;

beforeEach(async () => {
  clearTokenCache();
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  const id = await addBook(SLUG);
  await share(id, editor, "editor");
  await share(id, reader, "reader");
  gh = fakeNovels({
    [`${SLUG}/bible/characters/wade.md`]: "---\nname: Wade\n---\nRanch hand.\n",
    [`${SLUG}/bible/places/harlan-place.md`]: "---\nname: Harlan place\n---\n",
    [`${SLUG}/${SCENE}`]: `${HEADER}Wade opened the gate. <script>alert(1)</script>\n`,
  });
  vi.stubGlobal("fetch", gh.fetch);
  env = { ...testEnv, NOVELS_APP_ID: "123", NOVELS_APP_PRIVATE_KEY: key };
});

async function contextFor(email: string, e: Env = env) {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env: e, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(email));
  context.set(nonceContext, "test-nonce");
  return context;
}

async function settle<T>(p: Promise<T>): Promise<T | Response> {
  try {
    return await p;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown;
    throw thrown;
  }
}

function form(fields: Record<string, string>) {
  const body = new FormData();
  for (const [k, v] of Object.entries(fields)) body.set(k, v);
  return body;
}

async function bookPost(email: string, fields: Record<string, string>) {
  const request = new Request(`https://carrel.test/b/${SLUG}`, { method: "POST", body: form(fields) });
  return settle(bookAction({ request, params: { project: SLUG }, context: await contextFor(email) } as never));
}

async function openFile(email: string, path: string, e: Env = env, query = "") {
  const request = new Request(`https://carrel.test/b/${SLUG}/f/${path}${query}`);
  return settle(fileLoader({ request, params: { project: SLUG, "*": path }, context: await contextFor(email, e) } as never));
}

async function filePost(email: string, path: string, fields: Record<string, string>, e: Env = env) {
  const request = new Request(`https://carrel.test/b/${SLUG}/f/${path}`, { method: "POST", body: form(fields) });
  return settle(fileAction({ request, params: { project: SLUG, "*": path }, context: await contextFor(email, e) } as never));
}

async function exportAs(email: string, format: string) {
  const request = new Request(`https://carrel.test/b/${SLUG}/export/${format}`);
  return settle(exportLoader({ request, params: { project: SLUG, format }, context: await contextFor(email) } as never)) as Promise<Response>;
}

describe("the book view", () => {
  it("lists nothing until a refresh, then the chapters with each scene's header", async () => {
    const before = (await settle(bookLoader({ request: new Request("https://carrel.test/b/x"), params: { project: SLUG }, context: await contextFor("reader@test.invalid") } as never))) as Awaited<
      ReturnType<typeof bookLoader>
    >;
    expect(before.chapters).toEqual([]);
    expect(before.connected).toBe(true);

    const refreshed = (await bookPost("reader@test.invalid", { intent: "refresh" })) as { refreshed: { files: number } };
    expect(refreshed.refreshed.files).toBe(3);
    const after = (await bookLoader({ request: new Request("https://carrel.test/b/x"), params: { project: SLUG }, context: await contextFor("reader@test.invalid") } as never)) as Awaited<
      ReturnType<typeof bookLoader>
    >;
    expect(after.chapters).toMatchObject([{ slug: "01-arrival", title: "Arrival", scenes: [{ path: SCENE, name: "The gate", pov: "Wade", date: "2024-04-12" }] }]);
    expect(after.bible.map((b) => b.name)).toEqual(["Wade", "Harlan place"]);
  });

  it("PLANT: a Reader cannot start a chapter; an Editor is sent to the editor on the next number", async () => {
    expect(((await bookPost("reader@test.invalid", { intent: "new-chapter", name: "Letters" })) as Response).status).toBe(403);
    await bookPost("editor@test.invalid", { intent: "refresh" });
    const started = (await bookPost("editor@test.invalid", { intent: "new-chapter", name: "The Letters", scene: "Morning" })) as Response;
    expect(started.headers.get("Location")).toBe(`/b/${SLUG}/f/chapters/02-the-letters/01-morning.md`);
  });

  it("says why when Git is not connected, and still shows the index", async () => {
