// The social page through its loader and action: the Owner's alone, and an account added there
// starts off, in approval mode.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it } from "vitest";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { action as socialAction, loader as socialLoader } from "~/routes/social";

import { addPerson, addProject, resetDb, testEnv } from "./env";
import { viewerFor } from "./site";

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  await addPerson("editor@test.invalid");
  await addProject("germomics", "dustinedwards");
});

async function context(email: string) {
  const c = new RouterContextProvider();
  c.set(cloudflareContext, { env: testEnv, ctx: {} as ExecutionContext });
  c.set(viewerContext, await viewerFor(email));
  c.set(nonceContext, "n");
  return c;
}

describe("the social page", () => {
  it("PLANT: is 404 to anyone but the Owner", async () => {
    await expect(socialLoader({ request: new Request("https://carrel.test/social"), params: {}, context: await context("editor@test.invalid") } as never)).rejects.toMatchObject({ status: 404 });
  });

  it("adds an account that starts off, in approval mode, and says the routine is not set up", async () => {
    const body = new FormData();
    for (const [k, v] of Object.entries({ intent: "add-account", key: "germomics-bluesky", name: "Germomics", platform: "bluesky", kind: "brand", handle: "@germomics.bsky.social" })) body.set(k, v);
    expect(await socialAction({ request: new Request("https://carrel.test/social", { method: "POST", body }), params: {}, context: await context("owner@test.invalid") } as never)).toEqual({ ok: true });
    const data = (await socialLoader({ request: new Request("https://carrel.test/social"), params: {}, context: await context("owner@test.invalid") } as never)) as Awaited<ReturnType<typeof socialLoader>>;
    expect(data.accounts).toMatchObject([{ key: "germomics-bluesky", handle: "germomics.bsky.social", enabled: false, mode: "approval" }]);
    expect(data.routine).toBe("SOCIAL_ROUTINE_URL and SOCIAL_ROUTINE_TOKEN are not both set.");
  });
});

test/door.test.ts.source:
// The two doors (design decision 7, corrected 2026-09-27). The browser door is carrel.dustinedwards.info
// behind Access; the AI door is carrel-mcp.dustinedwards.info, an OAuth authorization server of its
// own with Cloudflare Access for SaaS as the sign-in. They are told apart by hostname, never by email.
//
// The AI door is driven end to end here: a CIMD client, the consent page, Access's sign-in (a fake
// Access for SaaS: its token and keys endpoints, answered through the stubbed fetch), the token
// endpoint, and a tool call with the token. Each planted refusal must end without a grant.

import { createExecutionContext } from "cloudflare:test";
import { createLocalJWKSet, exportJWK, generateKeyPair, SignJWT, type JWK } from "jose";
import { beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

import { aiDoor, isMcpHost } from "~/lib/mcp/door";

import { gate } from "../workers/gate";
import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { MCP_HOST, modernRequest, readMessage, type ToolCallResult } from "./mcp-client";
import { connectedEnv, fakeSite } from "./site";

const TEAM = "https://test-team.cloudflareaccess.com";
const BROWSER_AUD = "test-audience-tag";
const SAAS_CLIENT = "carrel-saas-client";
const SAAS_ISSUER = `${TEAM}/cdn-cgi/access/sso/oidc/${SAAS_CLIENT}`;
const DOOR = `https://${MCP_HOST}`;
const CLIENT_ID = "https://client.test/oauth/claude-code.json";
const REDIRECT = "https://client.test/callback";
const RESOURCE = `${DOOR}/mcp`;
const VERIFIER = "the-mcp-clients-own-pkce-verifier-0123456789abcdefghij";

let signingKey: CryptoKey;
let otherKey: CryptoKey;
let jwks: { keys: JWK[] };

beforeAll(async () => {
  const pair = await generateKeyPair("RS256", { extractable: true });
  signingKey = pair.privateKey;
  otherKey = (await generateKeyPair("RS256", { extractable: true })).privateKey;
  jwks = { keys: [{ ...(await exportJWK(pair.publicKey)), kid: "access", alg: "RS256", use: "sig" }] };
});

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  await addPerson("reviewer@test.invalid", { reviewer: true });
  await addPerson("gone@test.invalid", { disabled: true });
});

const doorEnv = (): Env => ({ ...testEnv, ACCESS_SAAS_CLIENT_ID: SAAS_CLIENT, ACCESS_SAAS_CLIENT_SECRET: "saas-secret" });

// ---------- the browser door

function accessToken(aud: string, email = "owner@test.invalid", key = signingKey) {
  return new SignJWT({ email }).setProtectedHeader({ alg: "RS256", kid: "access" }).setIssuer(TEAM).setAudience(aud).setIssuedAt().setExpirationTime("5m").sign(key);
}

async function browser(path: string, jwt: string) {
  let rendered = false;
  const response = await gate(
    new Request(`https://carrel.test${path}`, { headers: { "Cf-Access-Jwt-Assertion": jwt } }),
    testEnv,
    async () => {
      rendered = true;
      return new Response("inside");
    },
    createLocalJWKSet(jwks),
  );
  return { status: response.status, rendered };
}

describe("the browser door", () => {
  it("lets the browser's Access token in", async () => {
    expect(await browser("/", await accessToken(BROWSER_AUD))).toEqual({ status: 200, rendered: true });
  });

  it("PLANT: a token from any other Access application is refused, the retired MCP Access app's included", async () => {
    expect(await browser("/", await accessToken("test-mcp-audience-tag"))).toEqual({ status: 403, rendered: false });
  });

  it("PLANT: a reviewer is refused at the browser door", async () => {
    expect(await browser("/", await accessToken(BROWSER_AUD, "reviewer@test.invalid"))).toEqual({ status: 403, rendered: false });
  });

  it("PLANT: /mcp on the browser's host is a page behind Access like any other, never the AI door", async () => {
    expect(isMcpHost(new Request("https://carrel.test/mcp"), testEnv)).toBe(false);
    expect(await browser("/mcp", "")).toEqual({ status: 403, rendered: false });
  });
});

describe("which door", () => {
  it("is decided by the hostname alone", () => {
    expect(isMcpHost(new Request(`${DOOR}/mcp`), testEnv)).toBe(true);
    expect(isMcpHost(new Request(`${DOOR}/p/x/e/y`), testEnv)).toBe(true);
    expect(isMcpHost(new Request(`https://CARREL-MCP.test/mcp`), testEnv)).toBe(true);
    for (const url of ["https://carrel.test/mcp", "https://carrel-mcp.test.evil.example/mcp", "https://evil.example/carrel-mcp.test/mcp", "http://carrel-mcp.test:8443/mcp"]) {
      expect(isMcpHost(new Request(url), testEnv), url).toBe(false);
    }
  });
});

// ---------- the AI door

type Jar = Map<string, string>;

function remember(jar: Jar, response: Response) {
  for (const cookie of response.headers.getSetCookie()) {
    const [pair] = cookie.split(";");
    const at = pair!.indexOf("=");
    jar.set(pair!.slice(0, at), pair!.slice(at + 1));
  }
}

function cookieHeader(jar: Jar): string {
  return [...jar].map(([k, v]) => `${k}=${v}`).join("; ");
}

async function s256(value: string) {
  const digest = new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value)));
  return btoa(String.fromCharCode(...digest)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

type IdClaims = { email?: string; nonce?: string; aud?: string; iss?: string; key?: CryptoKey; email_verified?: boolean };

/** The fake Access for SaaS (and the client's CIMD document), behind the stubbed fetch. */
function fakeAccess(claims: (nonce: string) => IdClaims) {
  let nonce = "";
  const seen: string[] = [];
  const fetch = vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
    const request = new Request(input, init);
    seen.push(`${request.method} ${request.url}`);
    if (request.url === CLIENT_ID) {
      return Response.json({
        client_id: CLIENT_ID,
        client_name: "Claude Code",
        redirect_uris: [REDIRECT],
        grant_types: ["authorization_code", "refresh_token"],
        response_types: ["code"],
        token_endpoint_auth_method: "none",
      });
    }
    if (request.url === `${SAAS_ISSUER}/jwks`) return Response.json(jwks);
    if (request.url === `${SAAS_ISSUER}/token` && request.method === "POST") {
      const form = new URLSearchParams(await request.text());
      if (form.get("client_secret") !== "saas-secret" || form.get("code") !== "access-code" || !form.get("code_verifier")) return Response.json({ error: "invalid_grant" }, { status: 400 });
      const c = claims(nonce);
      const jwt = new SignJWT({ email: c.email ?? "owner@test.invalid", nonce: c.nonce ?? nonce, ...(c.email_verified === undefined ? {} : { email_verified: c.email_verified }) })
        .setProtectedHeader({ alg: "RS256", kid: "access" })
        .setIssuer(c.iss ?? SAAS_ISSUER)
        .setAudience(c.aud ?? SAAS_CLIENT)
        .setIssuedAt()
        .setExpirationTime("5m");
      return Response.json({ id_token: await jwt.sign(c.key ?? signingKey), access_token: "access-access-token", token_type: "Bearer" });
    }
    throw new Error(`the fake Access does not answer ${request.method} ${request.url}`);
  });
  return { fetch, seen, setNonce: (n: string) => (nonce = n) };
}

async function door(request: Request, env: Env = doorEnv()) {
  return aiDoor(request, env, createExecutionContext());
}

/**
 * Walks the whole sign-in. Returns the final redirect to the client (with a code, or an error), and
 * the Access authorization URL the browser was sent to.
 */
async function signIn(claims: (nonce: string) => IdClaims = () => ({}), opts: { decision?: "approve" | "deny"; accessError?: boolean } = {}) {
  const access = fakeAccess(claims);
  vi.stubGlobal("fetch", access.fetch);
  const jar: Jar = new Map();
  const authorize = new URL(`${DOOR}/authorize`);
  authorize.search = new URLSearchParams({
    response_type: "code",
    client_id: CLIENT_ID,
    redirect_uri: REDIRECT,
    state: "client-state",
    code_challenge: await s256(VERIFIER),
    code_challenge_method: "S256",
    scope: "carrel",
    resource: RESOURCE,
  }).toString();
  const page = await door(new Request(authorize));
  expect(page.status, await page.clone().text()).toBe(200);
  // The consent page is HTML: untransformed, so Web Analytics cannot inject its beacon into it.
  expect(page.headers.get("cache-control")).toBe("no-store, no-transform");
  remember(jar, page);
  const html = await page.text();
  expect(html).toContain("Allow Claude Code to use Carrel as you?");
  expect(html).toContain("client.test");
  const handle = /name="handle" value="([^"]+)"/.exec(html)![1]!;

  const approve = await door(
    new Request(`${DOOR}/authorize`, {
      method: "POST",
      headers: { Cookie: cookieHeader(jar), "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({ handle, decision: opts.decision ?? "approve" }),
    }),
  );
  expect(approve.status).toBe(302);
  remember(jar, approve);
  const toAccess = new URL(approve.headers.get("Location")!);
  if (opts.decision === "deny") return { final: toAccess, toAccess: null, access };

  expect(toAccess.origin + toAccess.pathname).toBe(`${SAAS_ISSUER}/authorization`);
  access.setNonce(toAccess.searchParams.get("nonce")!);
  const back = new URL(`${DOOR}/callback`);
  back.searchParams.set("state", toAccess.searchParams.get("state")!);
  if (opts.accessError) back.searchParams.set("error", "access_denied");
  else back.searchParams.set("code", "access-code");
  const done = await door(new Request(back, { headers: { Cookie: cookieHeader(jar) } }));
  expect(done.status).toBe(302);
  return { final: new URL(done.headers.get("Location")!), toAccess, access };
}

async function tokenFor(code: string): Promise<string> {
  const response = await door(
    new Request(`${DOOR}/token`, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({ grant_type: "authorization_code", code, redirect_uri: REDIRECT, client_id: CLIENT_ID, code_verifier: VERIFIER, resource: RESOURCE }),
    }),
  );
  const body = (await response.json()) as { access_token?: string };
  expect(response.status, JSON.stringify(body)).toBe(200);
  return body.access_token!;
}

async function callTool(token: string, name: string, args: Record<string, unknown> = {}, env?: Env): Promise<{ status: number; result?: ToolCallResult }> {
  const response = await door(modernRequest(7, "tools/call", { name, arguments: args }, { Authorization: `Bearer ${token}` }), env);
  if (response.status !== 200) return { status: response.status };
  return { status: 200, result: (await readMessage(response)).result as unknown as ToolCallResult };
}

describe("the AI door's OAuth surface", () => {
  it("answers /mcp without a token with a Bearer challenge that points at its metadata", async () => {
    const response = await door(modernRequest(1, "tools/list"));
    expect(response.status).toBe(401);
    expect(response.headers.get("WWW-Authenticate")).toContain(`resource_metadata="${DOOR}/.well-known/oauth-protected-resource/mcp"`);
    const meta = (await (await door(new Request(`${DOOR}/.well-known/oauth-protected-resource/mcp`))).json()) as Record<string, unknown>;
    expect(meta).toMatchObject({ resource: RESOURCE, authorization_servers: [DOOR] });
  });

  it("advertises CIMD and no registration endpoint, and /register does not exist", async () => {
    const meta = (await (await door(new Request(`${DOOR}/.well-known/oauth-authorization-server`))).json()) as Record<string, unknown>;
    expect(meta.client_id_metadata_document_supported).toBe(true);
    expect(meta.registration_endpoint).toBeUndefined();
    const register = await door(new Request(`${DOOR}/register`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ redirect_uris: [REDIRECT] }) }));
    expect(register.status).toBe(404);
  });

  it("PLANT: never serves Carrel's pages", async () => {
    for (const path of ["/", "/p/de-info", "/p/de-info/e/post-one/unpublish", "/social"]) {
      expect((await door(new Request(`${DOOR}${path}`))).status, path).toBe(404);
    }
  });

  it("PLANT: stays shut until the Access for SaaS app is configured", async () => {
    const response = await door(new Request(`${DOOR}/authorize?client_id=${encodeURIComponent(CLIENT_ID)}`), testEnv);
    expect(response.status).toBe(503);
  });
});

describe("signing in through Access for SaaS", () => {
  it("an Owner signs in, and the grant reaches the tools as that person, credited to the client", async () => {
    const { final, toAccess } = await signIn();
    expect(toAccess!.searchParams.get("client_id")).toBe(SAAS_CLIENT);
    expect(toAccess!.searchParams.get("redirect_uri")).toBe(`${DOOR}/callback`);
    expect(toAccess!.searchParams.get("code_challenge_method")).toBe("S256");
    expect(final.origin + final.pathname).toBe(REDIRECT);
    expect(final.searchParams.get("state")).toBe("client-state");
    const token = await tokenFor(final.searchParams.get("code")!);

    await addProject("de-info", "dustinedwards");
    const { result } = await callTool(token, "list_projects");
    expect(result!.structuredContent).toMatchObject({ projects: [{ slug: "de-info", role: "owner" }] });

    // The client is credited by its CIMD name on what it writes.
    const site = fakeSite();
    await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: One\n---\nWords.\n", expectedVersion: null, changeId: "seed" });
    const env = connectedEnv({ ACCESS_SAAS_CLIENT_ID: SAAS_CLIENT, ACCESS_SAAS_CLIENT_SECRET: "saas-secret" });
    vi.stubGlobal("fetch", site.fetch);
    await callTool(token, "add_finding", { project: "de-info", item: "post-one", message: "A flag." }, env);
    expect(await testEnv.DB.prepare("SELECT message FROM findings").first()).toEqual({ message: "A flag. (from Claude Code)" });
  });

  it("PLANT: OAuth is unchanged while an agent key is configured: the grant is still the person, an Owner here, never an agent", async () => {
    const { final } = await signIn();
    const token = await tokenFor(final.searchParams.get("code")!);
    await addProject("de-info", "dustinedwards");
    await addPerson("agent:grok");
    const withKey = connectedEnv({ ACCESS_SAAS_CLIENT_ID: SAAS_CLIENT, ACCESS_SAAS_CLIENT_SECRET: "saas-secret", AGENT_KEY_GROK: "grok-test-key-0123456789abcdefghijklmnop" });
    const site = fakeSite();
    vi.stubGlobal("fetch", site.fetch);
    const { status, result } = await callTool(token, "list_projects", {}, withKey);
    expect(status).toBe(200);
    expect(result!.structuredContent).toMatchObject({ projects: [{ slug: "de-info", role: "owner" }] });
    await callTool(token, "add_finding", { project: "de-info", item: "post-one", message: "A flag." }, withKey);
    expect(await testEnv.DB.prepare("SELECT message FROM findings").first()).toEqual({ message: "A flag. (from Claude Code)" });
    // And a token that is not a grant is still refused by the provider, not read as an agent key.
    expect((await callTool("not-a-token", "list_projects", {}, withKey)).status).toBe(401);
  });

  it("PLANT: Access let someone in whom Carrel does not know: refused, no code", async () => {
    const { final } = await signIn(() => ({ email: "stranger@test.invalid" }));
    expect(final.searchParams.get("error")).toBe("access_denied");
    expect(final.searchParams.get("error_description")).toBe("This person is not in Carrel.");
    expect(final.searchParams.get("code")).toBeNull();
  });

  it("PLANT: a disabled person is refused at sign-in", async () => {
    const { final } = await signIn(() => ({ email: "gone@test.invalid" }));
    expect(final.searchParams.get("error")).toBe("access_denied");
  });

  it("PLANT: an ID token with the wrong nonce, the wrong audience, a foreign key or an unverified email is refused", async () => {
    for (const claims of [
      { nonce: "replayed" },
      { aud: "some-other-saas-app" },
      { iss: `${TEAM}/cdn-cgi/access/sso/oidc/other` },
      { key: otherKey },
      { email_verified: false },
    ] satisfies IdClaims[]) {
      const { final } = await signIn(() => claims);
      expect(final.searchParams.get("error"), JSON.stringify(claims)).toBe("access_denied");
      expect(final.searchParams.get("code")).toBeNull();
    }
  });

  it("PLANT: Access reporting an error, and a person who clicks Deny, end with access_denied", async () => {
    expect((await signIn(undefined, { accessError: true })).final.searchParams.get("error")).toBe("access_denied");
    const denied = await signIn(undefined, { decision: "deny" });
    expect(denied.final.searchParams.get("error")).toBe("access_denied");
    expect(denied.access.seen.some((s) => s.includes("/token"))).toBe(false);
  });

  it("PLANT: a person disabled after the grant loses the door at once", async () => {
    const { final } = await signIn();
    const token = await tokenFor(final.searchParams.get("code")!);
    expect((await callTool(token, "list_projects")).status).toBe(200);
    await testEnv.DB.prepare("UPDATE people SET disabled_at = '2026-09-27T00:00:00Z' WHERE email = 'owner@test.invalid'").run();
    expect((await callTool(token, "list_projects")).status).toBe(403);
  });

  it("PLANT: a grant follows the person, not the email: the email moved to a new person row is refused", async () => {
    const { final } = await signIn();
    const token = await tokenFor(final.searchParams.get("code")!);
    expect((await callTool(token, "list_projects")).status).toBe(200);
    // The same email, now a different person (the row was replaced): the old grant must not carry over.
    await testEnv.DB.prepare("UPDATE people SET id = id + 1000 WHERE email = 'owner@test.invalid'").run();
    expect((await callTool(token, "list_projects")).status).toBe(403);
  });

  it("PLANT: a reviewer signs in through the same door and is refused a publish", async () => {
    const { final } = await signIn(() => ({ email: "reviewer@test.invalid" }));
    const token = await tokenFor(final.searchParams.get("code")!);
    const id = await addProject("de-info", "dustinedwards");
    const reviewer = await testEnv.DB.prepare("SELECT id FROM people WHERE email = 'reviewer@test.invalid'").first<{ id: number }>();
    await share(id, reviewer!.id, "reader");
    const { result } = await callTool(token, "publish", { project: "de-info", item: "post-one", expected_version: "v1" });
    expect(result).toMatchObject({ isError: true, content: [{ text: "A reviewer never publishes." }] });
  });

  it("PLANT: a forged or foreign bearer token is refused", async () => {
    expect((await callTool("not-a-token", "list_projects")).status).toBe(401);
    expect((await callTool(await accessToken(BROWSER_AUD), "list_projects")).status).toBe(401);
  });
});

test/history.test.ts.source:
// The history screens, driven through the route's loader with a real request context: a Reader may
// read all of it, nothing in it writes (to the site or to Carrel), and each comparison names the
// right two texts, older first.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { saveAiDraft } from "~/lib/ai.server";
import { autosave, writeToSite } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { orderPair } from "~/lib/history.server";
import { hasChanges, unifiedPatch } from "~/lib/patch";
import { requireSiteProject } from "~/lib/projects.server";
import { loader as historyLoader } from "~/routes/history";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
let site: ReturnType<typeof fakeSite>;
let env: Env;
let versions: string[];

const V1 = "---\ntitle: Post one\n---\nFirst words.\n";
const V2 = "---\ntitle: Post one\n---\nFirst words, revised.\n";
const V3 = "---\ntitle: Post one\n---\nFirst words, revised.\n\nA new closing paragraph.\n";

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const reader = await addPerson("reader@test.invalid");
  await addPerson("stranger@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, reader, "reader");
  site = fakeSite();
  vi.stubGlobal("fetch", site.fetch);
  env = connectedEnv();
  const owner = await viewerFor("owner@test.invalid");
  const project = await requireSiteProject(testEnv.DB, owner, SLUG, "publish");
  versions = [];
  let expected: string | null = null;
  for (const source of [V1, V2, V3]) {
    const saved = await writeToSite(env, project, owner, "post-one", { action: "save", source, expectedVersion: expected }, site.fetch);
    if (!saved.ok) throw new Error(saved.message);
    expected = saved.version;
    versions.push(saved.version);
  }
  site.requests.length = 0;
});

async function load(email: string, search = "") {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(email));
  context.set(nonceContext, "n");
  const request = new Request(`https://carrel.test/p/${SLUG}/e/post-one/history${search}`);
  return historyLoader({ request, params: { project: SLUG, item: "post-one" }, context } as never);
}

async function refusal(promise: Promise<unknown>): Promise<number> {
  try {
    await promise;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
  throw new Error("expected a refusal, and the call succeeded");
}

const changeRows = async () => (await testEnv.DB.prepare("SELECT COUNT(*) AS n FROM changes").first<{ n: number }>())!.n;

describe("reading history", () => {
  it("lists the revisions newest first for a Reader, and only reads", async () => {
    const before = await changeRows();
    const data = await load("reader@test.invalid");
    expect(data.revisions.map((r) => r.version)).toEqual([...versions].reverse());
    expect(data.revisions).toHaveLength(3);
    expect(site.requests.every((r) => r.startsWith("GET "))).toBe(true);
    expect(await changeRows()).toBe(before);
  });

  it("opens the source of an old revision", async () => {
    const data = await load("reader@test.invalid", `?version=${versions[0]}`);
    expect(data.view).toMatchObject({ kind: "source", source: V1, current: false, previous: null, newest: versions[2] });
    const newest = await load("reader@test.invalid", `?version=${versions[2]}`);
    expect(newest.view).toMatchObject({ kind: "source", source: V3, current: true, previous: versions[1], newest: null });
  });

  it("says plainly when the revision is not one the site holds", async () => {
    const data = await load("reader@test.invalid", "?version=nope");
    expect(data.view).toMatchObject({ kind: "problem", message: "The site has no such revision of this post." });
  });

  it("is answered 404 to someone with no role on the project, before the site is asked", async () => {
    expect(await refusal(load("stranger@test.invalid"))).toBe(404);
    expect(site.requests).toEqual([]);
  });
});

describe("comparing revisions", () => {
  it("sets the older revision against the newer whichever was picked first, from the site's own patch", async () => {
    const data = await load("reader@test.invalid", `?v=${versions[2]}&v=${versions[0]}`);
    expect(data.picked).toEqual([versions[0], versions[2]]);
    expect(data.view.kind).toBe("compare");
    const patch = (data.view as { patch: string }).patch;
    expect(patch).toContain("-First words.\n");
    expect(patch).toContain("+First words, revised.\n");
    expect(patch).toContain("+A new closing paragraph.\n");
    expect(site.requests).toContain("GET /api/carrel/v1/content/post-one/diff");
  });

  it("by word, hands the two revisions' texts to the word compare, older as Before", async () => {
    const data = await load("reader@test.invalid", `?v=${versions[0]}&v=${versions[1]}&by=word`);
    expect(data.view).toMatchObject({ kind: "compare", patch: null, before: { text: V1 }, after: { text: V2 } });
  });

  it("refuses one pick, the same pick twice and a pick the site does not hold, in words", async () => {
    for (const search of [`?v=${versions[0]}`, `?v=${versions[0]}&v=${versions[0]}`, `?v=${versions[0]}&v=nope`]) {
      const data = await load("reader@test.invalid", search);
      expect(data.view, search).toMatchObject({ kind: "problem", message: "Pick two different revisions to compare." });
    }
  });

  it("orders a pair by the site's list, newest first, so the older is always from", () => {
    const list = [
      { version: "c", at: "2026-10-03T00:00:00Z", author: "a", message: "" },
      { version: "b", at: "2026-10-02T00:00:00Z", author: "a", message: "" },
      { version: "a", at: "2026-10-01T00:00:00Z", author: "a", message: "" },
    ];
    expect(orderPair(list, ["c", "a"])).toMatchObject({ from: { version: "a" }, to: { version: "c" } });
    expect(orderPair(list, ["a", "c"])).toMatchObject({ from: { version: "a" }, to: { version: "c" } });
    expect(orderPair(list, ["a"])).toBeNull();
    expect(orderPair(list, ["a", "a"])).toBeNull();
    expect(orderPair(list, ["a", "z"])).toBeNull();
  });
});

describe("comparing the working draft", () => {
  async function ownDraft(source: string) {
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireSiteProject(testEnv.DB, owner, SLUG, "edit");
    await autosave(testEnv.DB, project, owner, "post-one", { source, baseVersion: versions[2]! });
    return { owner, project };
  }

  it("sets the draft against the site's text with a patch built here, and the site is only read", async () => {
    await ownDraft(V3.replace("A new closing paragraph.", "A different closing paragraph."));
    const data = await load("owner@test.invalid", "?compare=site");
    expect(data.view.kind).toBe("compare");
    const patch = (data.view as { patch: string }).patch;
    expect(patch).toContain("-A new closing paragraph.\n");
    expect(patch).toContain("+A different closing paragraph.\n");
    expect(site.requests.every((r) => r.startsWith("GET "))).toBe(true);
  });

  it("says there is nothing to compare when the person has no working draft", async () => {
    const data = await load("owner@test.invalid", "?compare=site");
    expect(data.view).toMatchObject({ kind: "problem" });
    expect((data.view as { message: string }).message).toMatch(/no working draft/);
  });

  it("sets the draft against an AI draft, and a draft that is not the viewer's is not found", async () => {
    const { owner, project } = await ownDraft(V3);
    const saved = await saveAiDraft(env, project, { viewer: owner, client: "Claude Code" }, "post-one", { source: V3.replace("First words, revised.", "First words, tightened."), note: "" }, site.fetch);
    const data = await load("owner@test.invalid", `?compare=ai&ai=${saved.id}`);
    const view = data.view as { kind: string; heading: string; patch: string };
    expect(view.kind).toBe("compare");
    expect(view.heading).toContain("AI draft from Claude Code");
    expect(view.patch).toContain("-First words, revised.\n");
    expect(view.patch).toContain("+First words, tightened.\n");
    expect(await refusal(load("reader@test.invalid", `?compare=ai&ai=${saved.id}`))).toBe(404);
  });
});

describe("the local patch", () => {
  it("names both sides but one file, shows only the changed lines with context, and says nothing changed when nothing did", () => {
    const patch = unifiedPatch("post-one.md", { text: "a\nb\nc\nd\ne\nf\ng\nh\n", label: "On the site" }, { text: "a\nb\nc\nD\ne\nf\ng\nh\n", label: "Your draft" });
    expect(patch).toContain("--- post-one.md\tOn the site");
    expect(patch).toContain("+++ post-one.md\tYour draft");
    expect(patch).toContain("-d\n+D\n");
    expect(hasChanges(patch)).toBe(true);
    const same = unifiedPatch("post-one.md", { text: "same\n", label: "a" }, { text: "same\n", label: "b" });
    expect(hasChanges(same)).toBe(false);
  });
});

test/google.test.ts.source:
// Google through the service account and Dustin's drive.file grant (design decision 6), against the
// fake Google in test/google.ts. Planted: a missing, broken, revoked or old key fails closed with a
// clear health message; a Drive write through the service account is refused in code, unsent.

import { beforeAll, beforeEach, describe, expect, it } from "vitest";

import { decryptToken, finishAuth, oauthConnection, startAuth } from "~/lib/google/oauth.server";
import { importFromDocs, listManuscripts, refreshManuscripts, searchManuscripts, sendToDocs } from "~/lib/google/drive.server";
import { pageStats, refreshSearchConsole } from "~/lib/google/search-console.server";
import { assertReadOnly, clearSaTokenCache, GoogleNotConnected, SA_SCOPES, saClient, ServiceAccountRefused } from "~/lib/google/service-account.server";
import { autosave, readDraft } from "~/lib/content.server";
import { runHealth } from "~/lib/health.server";
import { requireSiteProject } from "~/lib/projects.server";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { CLIENT_EMAIL, CODE, fakeGoogle, KEY_ID, REFRESH, serviceAccountKey } from "./google";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const FOLDER = "folderRoot1";
const TOKEN_KEY = btoa(String.fromCharCode(...new Uint8Array(32).map((_, i) => i + 1)));
const SLUG = "de-info";

let key: Awaited<ReturnType<typeof serviceAccountKey>>;
beforeAll(async () => {
  key = await serviceAccountKey();
});

let google: ReturnType<typeof fakeGoogle>;
let site: ReturnType<typeof fakeSite>;
let env: Env;

function googleEnv(overrides: Record<string, string | undefined> = {}): Env {
  return {
    ...connectedEnv(),
    GOOGLE_SA_KEY: key.json,
    GOOGLE_OAUTH_CLIENT_ID: "client-id.apps.googleusercontent.com",
    GOOGLE_OAUTH_CLIENT_SECRET: "client-secret",
    GOOGLE_TOKEN_KEY: TOKEN_KEY,
    GOOGLE_MANUSCRIPTS_FOLDER_ID: FOLDER,
    ...overrides,
  } as Env;
}

/** Google or the site, by origin, as the Worker's one fetch would reach either. */
function both(): typeof fetch {
  return (async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = new Request(input, init).url;
    return url.startsWith("https://site.test") ? site.fetch(input, init) : google.fetch(input, init);
  }) as typeof fetch;
}

beforeEach(async () => {
  clearSaTokenCache();
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, editor, "editor");
  google = fakeGoogle({
    publicJwk: key.publicJwk,
    files: [
      { id: "m1", name: "Grant proposal", mimeType: "application/vnd.google-apps.document", parent: FOLDER, content: "Aims: stromatolites of the Paluxy." },
      { id: "sub1", name: "Papers", mimeType: "application/vnd.google-apps.folder", parent: FOLDER },
      { id: "m2", name: "Trackways paper", mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document", parent: "sub1", content: "Theropod trackways in the riverbed." },
      { id: "elsewhere", name: "Not a manuscript", mimeType: "application/vnd.google-apps.document", parent: "someOtherFolder", content: "trackways too" },
    ],
    scRows: [{ keys: ["https://site.test/blog/post-one"], clicks: 12, impressions: 340, ctr: 0.035, position: 8.44 }],
  });
  site = fakeSite();
  env = googleEnv();
});

describe("the service account", () => {
  it("asks for an access token with a JWT signed by its key, for read-only scopes, once an hour", async () => {
    const sa = saClient(env, google.fetch);
    await sa.request("GET", `https://www.googleapis.com/drive/v3/files?q=x`);
    await sa.request("GET", `https://www.googleapis.com/drive/v3/files?q=y`);
    expect(google.assertions).toHaveLength(1);
    expect(google.assertions[0]).toMatchObject({ iss: CLIENT_EMAIL, scope: SA_SCOPES.join(" ") });
  });

  it("never asks for drive.readonly, or any scope that writes", () => {
    expect(SA_SCOPES).toEqual(["https://www.googleapis.com/auth/drive.metadata.readonly", "https://www.googleapis.com/auth/webmasters.readonly"]);
  });

  it("PLANT: a Drive write through the service account is refused in code, before anything is sent", async () => {
    const sa = saClient(env, google.fetch);
    const attempts: [string, string][] = [
      ["POST", "https://www.googleapis.com/drive/v3/files"],
      ["POST", "https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart"],
      ["PATCH", "https://www.googleapis.com/drive/v3/files/m1?fields=id"],
      ["DELETE", "https://www.googleapis.com/drive/v3/files/m1?supportsAllDrives=true"],
      ["POST", "https://www.googleapis.com/drive/v3/files/m1/copy"],
      ["POST", "https://www.googleapis.com/drive/v3/files/m1/permissions"],
      // Reading a file's text is not the service account's either.
      ["GET", "https://www.googleapis.com/drive/v3/files/m1/export?mimeType=text/plain"],
      ["GET", "https://www.googleapis.com/drive/v3/files/m1?alt=media"],
      ["PUT", "https://searchconsole.googleapis.com/webmasters/v3/sites/x/sitemaps/y"],
    ];
    for (const [method, url] of attempts) {
      await expect(sa.request(method, url), `${method} ${url}`).rejects.toBeInstanceOf(ServiceAccountRefused);
    }
    expect(google.requests).toEqual([]);
    // And the reads it does make pass.
    expect(() => assertReadOnly("GET", "https://www.googleapis.com/drive/v3/files?q=x")).not.toThrow();
  });

  it("PLANT: a missing key fails closed: no request, and a clear reason", () => {
    expect(() => saClient(googleEnv({ GOOGLE_SA_KEY: undefined }), google.fetch)).toThrow(GoogleNotConnected);
    expect(() => saClient(googleEnv({ GOOGLE_SA_KEY: "{not json" }), google.fetch)).toThrow("GOOGLE_SA_KEY is not JSON");
    const elsewhere = JSON.stringify({ ...JSON.parse(key.json), token_uri: "https://evil.example/token" });
    expect(() => saClient(googleEnv({ GOOGLE_SA_KEY: elsewhere }), google.fetch)).toThrow("not Google's");
    expect(google.requests).toEqual([]);
  });
});

describe("health for Google", () => {
  const certs = async (url: string, init?: RequestInit) =>
    url.includes("cloudflareaccess.com") ? Response.json({ keys: [{ kid: "k" }] }) : google.fetch(url, init);
  const mailbox = () => ({ send: async () => ({ messageId: "m" }) }) as unknown as SendEmail;

  async function check(e: Env, name: string, now = new Date("2026-09-27T00:00:00Z")) {
    const { results } = await runHealth({ ...e, EMAIL: mailbox() }, certs, () => now);
    return results.find((r) => r.name === name)!;
  }

  it("reports a key that works and its age from the first time it was seen", async () => {
    expect(await check(env, "google-service-account")).toEqual({ name: "google-service-account", ok: true, detail: `Key ${KEY_ID.slice(0, 8)} (${CLIENT_EMAIL}) works; 0 days old.` });
    clearSaTokenCache();
    expect((await check(env, "google-service-account", new Date("2026-10-27T00:00:00Z"))).detail).toContain("works; 30 days old.");
  });

  it("PLANT: a missing key says so plainly, as not connected yet", async () => {
    expect(await check(googleEnv({ GOOGLE_SA_KEY: undefined }), "google-service-account")).toEqual({
      name: "google-service-account",
      ok: true,
      detail: "Not connected: GOOGLE_SA_KEY is not set, so the manuscripts index and Search Console are off.",
    });
  });

  it("PLANT: a key Google refuses (deleted, disabled, expired) fails with what to do", async () => {
    google.state.saRevoked = true;
    const result = await check(env, "google-service-account");
    expect(result.ok).toBe(false);
    expect(result.detail).toMatch(/^Key 01234567 \(carrel-reader@.+\) no longer works: Google refused the service account key \(400 invalid_grant: Invalid JWT Signature\.\)\. Create a new key and set GOOGLE_SA_KEY\.$/);
  });

  it("PLANT: a key past 90 days fails, asking for rotation", async () => {
    await check(env, "google-service-account", new Date("2026-06-01T00:00:00Z"));
    clearSaTokenCache();
    const result = await check(env, "google-service-account", new Date("2026-09-27T00:00:00Z"));
    expect(result).toMatchObject({ ok: false, detail: "Key 01234567 is 118 days old, past 90. Create a new key, set GOOGLE_SA_KEY, then delete the old one in Google Cloud." });
  });

  it("PLANT: a revoked drive.file grant fails; none connected is not a failure", async () => {
    expect(await check(env, "google-drive-file")).toMatchObject({ ok: true, detail: expect.stringMatching(/^Not connected: no one has connected/) });
    await connectGoogle();
    expect(await check(env, "google-drive-file")).toMatchObject({ ok: true });
    google.state.userRevoked = true;
    expect(await check(env, "google-drive-file")).toMatchObject({ ok: false, detail: expect.stringContaining("Google refused the drive.file grant (400 invalid_grant)") });
  });
});

describe("the manuscripts index", () => {
  it("walks the shared folder and its subfolders, keeping metadata and no text", async () => {
    const result = await refreshManuscripts(env, google.fetch);
    expect(result).toEqual({ files: 2, removed: 0, folders: 2, more: false });
    const owner = await viewerFor("owner@test.invalid");
    const list = await listManuscripts(testEnv.DB, owner);
    expect(list.map((m) => [m.name, m.folder, m.people])).toEqual(
      expect.arrayContaining([
        ["Grant proposal", "", ["Dustin Edwards", "A Coauthor"]],
        ["Trackways paper", "Papers", ["Dustin Edwards", "A Coauthor"]],
      ]),
    );
    // Not a word of either manuscript is in Carrel's database.
    const dump = JSON.stringify(await testEnv.DB.prepare("SELECT * FROM manuscripts").all());
    expect(dump).not.toContain("stromatolites");
    expect(dump).not.toContain("Theropod");
  });

  it("picks up files added later and drops files removed", async () => {
    await refreshManuscripts(env, google.fetch);
    google.files.push({ id: "m3", name: "New chapter", mimeType: "application/pdf", parent: "sub1" });
    google.files.splice(google.files.findIndex((f) => f.id === "m1"), 1);
    expect(await refreshManuscripts(env, google.fetch)).toMatchObject({ files: 2, removed: 1 });
    const names = (await listManuscripts(testEnv.DB, await viewerFor("owner@test.invalid"))).map((m) => m.name).sort();
    expect(names).toEqual(["New chapter", "Trackways paper"]);
  });

  it("searches the text through Drive, and returns only files in the folder", async () => {
    await refreshManuscripts(env, google.fetch);
    const owner = await viewerFor("owner@test.invalid");
    expect(await searchManuscripts(env, owner, "trackways", google.fetch)).toMatchObject({ searched: "text", files: [{ name: "Trackways paper" }] });
    expect((await searchManuscripts(env, owner, "no such words", google.fetch)).files).toEqual([]);
    // Quotes in the search are escaped for Drive's query language, not injected into it.
    expect((await searchManuscripts(env, owner, "x' or name contains 'a", google.fetch)).files).toEqual([]);
  });

  it("falls back to titles, and says so, if Drive will not run a full-text query for this access", async () => {
    await refreshManuscripts(env, google.fetch);
    google.state.refuseFullText = true;
    const owner = await viewerFor("owner@test.invalid");
    expect(await searchManuscripts(env, owner, "grant", google.fetch)).toMatchObject({ searched: "titles", files: [{ name: "Grant proposal" }] });
  });

  it("PLANT: manuscripts are the Owner's alone", async () => {
    const editor = await viewerFor("editor@test.invalid");
    await expect(listManuscripts(testEnv.DB, editor)).rejects.toMatchObject({ status: 404 });
    await expect(searchManuscripts(env, editor, "x", google.fetch)).rejects.toMatchObject({ status: 404 });
  });
});

async function connectGoogle() {
  const owner = await viewerFor("owner@test.invalid");
  const start = new URL(await startAuth(env, owner, "https://carrel.test"));
  return finishAuth(env, owner, new URLSearchParams({ state: start.searchParams.get("state")!, code: CODE }), "https://carrel.test", google.fetch);
}

describe("connecting drive.file", () => {
  it("asks Google for drive.file alone, offline, back to Carrel's own callback", async () => {
    const start = new URL(await startAuth(env, await viewerFor("owner@test.invalid"), "https://carrel.test"));
    expect(start.origin + start.pathname).toBe("https://accounts.google.com/o/oauth2/v2/auth");
    expect(Object.fromEntries(start.searchParams)).toMatchObject({
      scope: "https://www.googleapis.com/auth/drive.file",
      access_type: "offline",
      redirect_uri: "https://carrel.test/auth/google/callback",
      response_type: "code",
    });
  });

  it("stores the refresh token encrypted, never as it came", async () => {
    expect(await connectGoogle()).toEqual({ ok: true });
    const row = await testEnv.DB.prepare("SELECT refresh_token, iv, scope FROM google_tokens").first<{ refresh_token: string; iv: string; scope: string }>();
    expect(row!.refresh_token).not.toContain(REFRESH);
    const c = await oauthConnection(env);
    if (c.state !== "configured" || !c.key) throw new Error("not configured");
    expect(await decryptToken(c.key, row!.refresh_token, row!.iv)).toBe(REFRESH);
  });

  it("PLANT: a callback Carrel did not start, or one used twice, is refused", async () => {
    const owner = await viewerFor("owner@test.invalid");
    expect(await finishAuth(env, owner, new URLSearchParams({ state: "forged", code: CODE }), "https://carrel.test", google.fetch)).toMatchObject({ ok: false });
    const start = new URL(await startAuth(env, owner, "https://carrel.test"));
    const params = new URLSearchParams({ state: start.searchParams.get("state")!, code: CODE });
    expect(await finishAuth(env, owner, params, "https://carrel.test", google.fetch)).toEqual({ ok: true });
    expect(await finishAuth(env, owner, params, "https://carrel.test", google.fetch)).toMatchObject({ ok: false });
  });

  it("PLANT: a grant wider than drive.file is refused and nothing is stored", async () => {
    google.state.grantedScope = "https://www.googleapis.com/auth/drive.file https://www.googleapis.com/auth/drive.readonly";
    const result = await connectGoogle();
    expect(result).toMatchObject({ ok: false, message: expect.stringContaining("Carrel keeps only a drive.file grant") });
    expect(await testEnv.DB.prepare("SELECT COUNT(*) AS n FROM google_tokens").first()).toEqual({ n: 0 });
  });

  it("PLANT: only the Owner connects Google", async () => {
    await expect(startAuth(env, await viewerFor("editor@test.invalid"), "https://carrel.test")).rejects.toMatchObject({ status: 403 });
  });
});

describe("Send to Docs and Import", () => {
  async function seeded() {
    await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Post one\n---\nThe body, with *emphasis*.\n", expectedVersion: null, changeId: "s" });
    await connectGoogle();
    const owner = await viewerFor("owner@test.invalid");
    return { owner, project: await requireSiteProject(testEnv.DB, owner, SLUG, "read") };
  }

  it("sends the post's body as a new Doc and keeps its frontmatter in Carrel", async () => {
    const { owner, project } = await seeded();
    const sent = await sendToDocs(env, project, owner, "post-one", both());
    expect(sent).toMatchObject({ ok: true, url: "https://docs.google.com/document/d/doc1/edit" });
    expect(google.docs.get("doc1")).toEqual({ name: "Post one (from Carrel)", content: "The body, with *emphasis*.\n" });
  });

  it("imports the Doc's text as a new draft under the post's frontmatter, leaving the site alone", async () => {
    const { owner, project } = await seeded();
    await sendToDocs(env, project, owner, "post-one", both());
    google.state.docEdits.set("doc1", "The body, edited by a coauthor.\n");
    expect(await importFromDocs(env, project, owner, "post-one", both())).toEqual({ ok: true, words: 6 });
    expect((await readDraft(testEnv.DB, project, owner, "post-one"))?.source).toBe("---\ntitle: Post one\n---\nThe body, edited by a coauthor.\n");
    expect((await site.adapter.content.get("post-one"))?.source).toBe("---\ntitle: Post one\n---\nThe body, with *emphasis*.\n");
  });

  it("PLANT: an import never replaces a working draft", async () => {
    const { owner, project } = await seeded();
    await sendToDocs(env, project, owner, "post-one", both());
    await autosave(testEnv.DB, project, owner, "post-one", { source: "My unsaved words.", baseVersion: null });
    expect(await importFromDocs(env, project, owner, "post-one", both())).toMatchObject({ ok: false, message: expect.stringContaining("an import never replaces a draft") });
    expect((await readDraft(testEnv.DB, project, owner, "post-one"))?.source).toBe("My unsaved words.");
  });

  it("PLANT: an Editor cannot send outside Carrel", async () => {
    await seeded();
    const editor = await viewerFor("editor@test.invalid");
    const project = await requireSiteProject(testEnv.DB, editor, SLUG, "read");
    await expect(sendToDocs(env, project, editor, "post-one", both())).rejects.toMatchObject({ status: 403 });
    expect(google.docs.size).toBe(0);
  });

  it("PLANT: without a connected grant, Send fails closed and says how to connect", async () => {
    await site.adapter.content.saveDraft("post-one", { source: "x", expectedVersion: null, changeId: "s" });
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireSiteProject(testEnv.DB, owner, SLUG, "read");
    await expect(sendToDocs(env, project, owner, "post-one", both())).rejects.toThrow("Google is not connected for Send to Docs yet.");
    expect(google.docs.size).toBe(0);
  });
});

describe("Search Console", () => {
  it("reads 28 days per page, settled data only, at most once a day, and finds a post's row by its URL", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireSiteProject(testEnv.DB, owner, SLUG, "read");
    const now = new Date("2026-09-27T12:00:00Z");
    expect(await refreshSearchConsole(env, project, google.fetch, now)).toEqual({ pages: 1, skipped: false, start: "2026-08-28", end: "2026-09-24" });
    expect(google.requests.filter((r) => r.includes("searchAnalytics"))).toEqual([
      "POST https://searchconsole.googleapis.com/webmasters/v3/sites/sc-domain%3Adustinedwards.info/searchAnalytics/query",
    ]);
    expect((await refreshSearchConsole(env, project, google.fetch, new Date("2026-09-27T20:00:00Z"))).skipped).toBe(true);
    expect(await pageStats(env, project, "/blog/post-one")).toMatchObject({ clicks: 12, impressions: 340, position: 8.44 });
    expect(await pageStats(env, project, "/blog/other")).toBeNull();
  });

  it("says what to do when the service account is not on the property", async () => {
    google.state.scStatus = 403;
    const project = await requireSiteProject(testEnv.DB, await viewerFor("owner@test.invalid"), SLUG, "read");
    await expect(refreshSearchConsole(env, project, google.fetch)).rejects.toThrow("Add the service account as a user on the property in Search Console.");
  });
});

test/kinds.test.ts.source:
// Every kind the site reports, end to end through the routes: a non-post kind lists under its own
// kind and filter, opens, saves, previews, publishes and shows its revisions exactly as a post does,
// and a data kind the site will not write stays out of the lists and, if reached, shows the site's
// own refusal. Carrel has no per-kind code; the kinds and paths come from the site.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { refreshIndex } from "~/lib/index.server";
import { action as editorAction, loader as editorLoader } from "~/routes/editor";
import { loader as historyLoader } from "~/routes/history";
import { loader as previewLoader } from "~/routes/preview";
import { loader as projectLoader } from "~/routes/project";

import { addPerson, addProject, resetDb } from "./env";
import { connectedEnv, fakeSite, kindedAdapter, viewerFor } from "./site";

const SLUG = "de-info";
const OWNER = "owner@test.invalid";
let projectId = 0;

beforeEach(async () => {
  await resetDb();
  await addPerson(OWNER, { owner: true });
  projectId = await addProject(SLUG, "dustinedwards");
});

async function contextFor(env: Env) {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(OWNER));
  context.set(nonceContext, "test-nonce");
  return context;
}

async function settled<T>(run: () => Promise<T>): Promise<T | Response> {
  try {
    return await run();
  } catch (thrown) {
    if (thrown instanceof Response) return thrown;
    throw thrown;
  }
}

async function seeded() {
  const site = fakeSite(kindedAdapter());
  vi.stubGlobal("fetch", site.fetch);
  const env = connectedEnv();
  const put = async (id: string, source: string, publish: boolean) => {
    const saved = await site.adapter.content.saveDraft(id, { source, expectedVersion: null, changeId: `seed-${id}` });
    if (publish) await site.adapter.content.publish(id, { expectedVersion: saved.version, changeId: `seed-pub-${id}` });
  };
  await put("a-post", "---\ntitle: A post\n---\nWords.\n", true);
  await put("draft-post", "---\ntitle: A draft post\n---\nNot yet.\n", false);
  await put("phage.acorn15", "---\ntitle: Acorn15\nhost: Gordonia\n---\nA cluster DJ phage.\n", true);
  await put("roster.2017", "---\ntitle: 2017 cohort\nyear: 2017\n---\n", true);
  await put("procedure.coi-primers", "---\ntitle: COI primers\n---\nThe PCR protocol.\n", true);
  await refreshIndex(env, { id: projectId, site: "dustinedwards" });
  return { site, env };
}

const form = (fields: Record<string, string>) => {
  const body = new FormData();
  for (const [k, v] of Object.entries(fields)) body.set(k, v);
  return body;
};

describe("every kind the site reports", () => {
  it("lists each writing kind under its own kind, and the kind filter narrows to it", async () => {
    const { env } = await seeded();
    const context = await contextFor(env);
    const all = (await projectLoader({ request: new Request(`https://carrel.test/p/${SLUG}`), params: { project: SLUG }, context } as never)) as Awaited<ReturnType<typeof projectLoader>>;
    expect(all.kinds).toEqual(["phage", "post", "procedure", "roster"]);
    const byId = Object.fromEntries(all.items.map((i) => [i.itemId, i]));
    expect(byId["phage.acorn15"]).toMatchObject({ kind: "phage", path: "/research/phages#acorn15", status: "published" });
    expect(byId["roster.2017"]).toMatchObject({ kind: "roster", path: "/teaching/phage-discovery#year-2017" });
    expect(byId["procedure.coi-primers"]).toMatchObject({ kind: "procedure", path: "/research/protocols/coi-primers" });
    expect(byId["draft-post"]).toMatchObject({ kind: "post", status: "draft", path: null });

    const phages = (await projectLoader({ request: new Request(`https://carrel.test/p/${SLUG}?kind=phage`), params: { project: SLUG }, context } as never)) as Awaited<ReturnType<typeof projectLoader>>;
    expect(phages.items.map((i) => i.itemId)).toEqual(["phage.acorn15"]);
  });

  it("opens, saves, previews, publishes and shows the history of a non-post kind", async () => {
    const { env, site } = await seeded();
    const id = "phage.acorn15";
    const params = { project: SLUG, item: id };
    const url = `https://carrel.test/p/${SLUG}/e/${id}`;

    const opened = (await editorLoader({ request: new Request(url), params, context: await contextFor(env) } as never)) as Awaited<ReturnType<typeof editorLoader>>;
    expect(opened.title).toBe("Acorn15");
    expect(opened.path).toBe("/research/phages#acorn15");
    // Links written in the editor go to each item's own address on the site, a draft post to where the site's posts live.
    expect(opened.linkTargets.map((t) => t.href).sort()).toEqual([
      "/research/protocols/coi-primers",
      "/teaching/phage-discovery#year-2017",
      "/writing/a-post",
      "/writing/draft-post",
    ]);

    const source = "---\ntitle: Acorn15\nhost: Gordonia terrae\n---\nA cluster DJ phage, found in 2015.\n";
    const saved = await editorAction({ request: new Request(url, { method: "POST", body: form({ intent: "save", source, expectedVersion: opened.version! }) }), params, context: await contextFor(env) } as never);
    expect(saved).toMatchObject({ intent: "write", outcome: { ok: true, action: "save", status: "published" } });
    const version = (saved as { outcome: { version: string } }).outcome.version;

    const previewed = (await settled(async () => previewLoader({ request: new Request(`${url}/preview`), params, context: await contextFor(env) } as never))) as Response;
    expect(previewed.status).toBe(200);
    expect(await previewed.text()).toContain("found in 2015");

    const published = await editorAction({ request: new Request(url, { method: "POST", body: form({ intent: "publish", source, expectedVersion: version }) }), params, context: await contextFor(env) } as never);
    expect(published).toMatchObject({ intent: "write", outcome: { ok: true, action: "publish", status: "published" } });
    expect((await site.adapter.content.get(id))?.source).toContain("found in 2015");

    const history = (await historyLoader({ request: new Request(`${url}/history`), params, context: await contextFor(env) } as never)) as { revisions: unknown[] | null };
    expect(history.revisions?.length).toBe(4);
  });

  it("keeps a data kind out of the lists, and shows the site's own refusal if one is written", async () => {
    const { env, site } = await seeded();
    // The site's import puts registry rows in place directly; Carrel never wrote them.
    await env.DB.prepare("INSERT INTO site_items (project_id, item_id, kind, title, status, synced_at) VALUES (?, 'equipment.heat-block', 'equipment', 'Heat block', 'published', '2026-10-10T00:00:00Z')").bind(projectId).run();
    const context = await contextFor(env);
    const listed = (await projectLoader({ request: new Request(`https://carrel.test/p/${SLUG}`), params: { project: SLUG }, context } as never)) as Awaited<ReturnType<typeof projectLoader>>;
    expect(listed.kinds).not.toContain("equipment");
    expect(listed.items.map((i) => i.itemId)).not.toContain("equipment.heat-block");

    const params = { project: SLUG, item: "equipment.heat-block" };
    const written = await editorAction({
      request: new Request(`https://carrel.test/p/${SLUG}/e/equipment.heat-block`, { method: "POST", body: form({ intent: "save", source: "---\nname: Heat block\n---\n", expectedVersion: "" }) }),
      params,
      context: await contextFor(env),
    } as never);
    expect(written).toMatchObject({ intent: "write", outcome: { ok: false, reason: "refused", message: "The site's equipment entries are edited in the site's repository, not through Carrel." } });
    expect(await site.adapter.content.get("equipment.heat-block")).toBeNull();
  });
});

test/books.test.ts.source:
// Books through Carrel's service layer, against the fake novels repository: who may open, save and
// export; a save that commits with the version it expects and records who wrote what; the checks
// that run on save and never stop it; and export held while a flag is open.

import { beforeEach, describe, expect, it } from "vitest";

import {
  assembleBook,
  authorshipRecord,
  authorshipReport,
  checkDraft,
  createBook,
  dismissFinding,
  exportGate,
  listFiles,
  listFindings,
  refreshBook,
  requireBookProject,
  saveBookFile,
  wordDelta,
} from "~/lib/books.server";
import { autosave, readDraft } from "~/lib/content.server";
import { requireSiteProject } from "~/lib/projects.server";

import { addBook, addPerson, addProject, resetDb, share, testEnv } from "./env";
import { BASELINE, PLANT } from "./fixtures/voice";
import { fakeNovels } from "./novels";
import { viewerFor } from "./site";

const SLUG = "test-book";

const WADE = "---\nname: Wade Pruitt\naliases: [Wade]\nborn: 1996-02-11\n---\nRanch hand.\n";
const PLACE = "---\nname: Harlan place\n---\n";
const RULE = "---\nname: No phones past the ridge\nforbidden: [phone rang]\n---\n";
const HEADER = "---\npov: Wade\ndate: 2024-04-12\nlocation: Harlan place\ncharacters: [Wade]\ngoal: get in\nconflict: the lock\noutcome: he opens it\n---\n\n";

function seedRepo(extra: Record<string, string> = {}) {
  return fakeNovels({
    [`${SLUG}/book.md`]: "---\ntitle: The Test Book\nauthor: Test Author\n---\n",
    [`${SLUG}/bible/characters/wade.md`]: WADE,
    [`${SLUG}/bible/places/harlan-place.md`]: PLACE,
    [`${SLUG}/bible/rules/phones.md`]: RULE,
    [`${SLUG}/chapters/01-arrival/01-the-gate.md`]: `${HEADER}Wade opened the gate.\n`,
    [`${SLUG}/chapters/01-arrival/02-supper.md`]: HEADER.replace("2024-04-12", "2024-04-12 19:00") + "They ate at the kitchen table.\n",
    [`${SLUG}/outline/plan.md`]: "# Plan\n",
    [`${SLUG}/build/book.epub`]: "ignored",
    [`${SLUG}/notes.txt`]: "ignored",
    "shared/checks/ai-habits.md": "---\nwords: [suddenly]\n---\n",
    ...extra,
  });
}

async function refusal(promise: Promise<unknown>): Promise<number> {
  try {
    await promise;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
  throw new Error("expected a refusal, and the call succeeded");
}

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  await addPerson("stranger@test.invalid");
  const id = await addBook(SLUG);
  await share(id, editor, "editor");
  await share(id, reader, "reader");
});

async function as(email: string, action: "read" | "edit" | "publish" = "read") {
  const viewer = await viewerFor(email);
  return { viewer, project: await requireBookProject(testEnv.DB, viewer, SLUG, action) };
}

describe("opening a book", () => {
  it("PLANT: a non-member, a missing book, and a site all answer 404", async () => {
    const stranger = await viewerFor("stranger@test.invalid");
    const owner = await viewerFor("owner@test.invalid");
    await addProject("a-site", "dustinedwards");
    expect(await refusal(requireBookProject(testEnv.DB, stranger, SLUG, "read"))).toBe(404);
    expect(await refusal(requireBookProject(testEnv.DB, owner, "no-such-book", "read"))).toBe(404);
    expect(await refusal(requireBookProject(testEnv.DB, owner, "a-site", "read"))).toBe(404);
    // And the other way: a book is not a site.
    expect(await refusal(requireSiteProject(testEnv.DB, owner, SLUG, "read"))).toBe(404);
  });

  it("PLANT: a Reader asking to edit is refused 403", async () => {
    const reader = await viewerFor("reader@test.invalid");
    expect(await refusal(requireBookProject(testEnv.DB, reader, SLUG, "edit"))).toBe(403);
  });

  it("creates a book for the Owner only, with a folder name the layout allows", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const editor = await viewerFor("editor@test.invalid");
    expect(await refusal(createBook(testEnv.DB, editor, { name: "Mine", folder: "mine" }))).toBe(403);
    expect(await createBook(testEnv.DB, owner, { name: "Paluxy Portal", folder: "paluxy-portal" })).toEqual({ ok: true, slug: "paluxy-portal" });
    expect((await createBook(testEnv.DB, owner, { name: "Again", folder: "paluxy-portal" })).ok).toBe(false);
    expect((await createBook(testEnv.DB, owner, { name: "Bad", folder: "../etc" })).ok).toBe(false);
    expect((await createBook(testEnv.DB, owner, { name: "Shared", folder: "shared" })).ok).toBe(false);
  });
});

describe("refresh from Git", () => {
  it("indexes the book's Markdown files by kind, skips build/ and other files, and reads shared/", async () => {
    const gh = seedRepo();
    const { project } = await as("reader@test.invalid");
    const result = await refreshBook(testEnv.DB, gh.repo, project);
    expect(result).toMatchObject({ files: 7, read: 7, removed: 0, shared: 1, more: false });
    const files = await listFiles(testEnv.DB, project);
    expect(files.map((f) => [f.path, f.kind])).toEqual([
      ["bible/characters/wade.md", "character"],
      ["bible/places/harlan-place.md", "place"],
      ["bible/rules/phones.md", "rule"],
      ["book.md", "book"],
      ["chapters/01-arrival/01-the-gate.md", "scene"],
      ["chapters/01-arrival/02-supper.md", "scene"],
      ["outline/plan.md", "outline"],
    ]);
    // A clean book has nothing flagged.
    expect(await listFindings(testEnv.DB, project)).toEqual([]);
  });

  it("reads again only what changed, and drops what Git no longer has", async () => {
    const gh = seedRepo();
    const { project } = await as("reader@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    gh.files.delete(`${SLUG}/outline/plan.md`);
    await gh.commitElsewhere(`${SLUG}/chapters/01-arrival/02-supper.md`, `${HEADER}Suddenly they ate.\n`);
    const before = gh.requests.length;
    expect(await refreshBook(testEnv.DB, gh.repo, project)).toMatchObject({ read: 1, removed: 1, shared: 0 });
    expect(gh.requests.slice(before).filter((r) => r.includes("/contents/"))).toEqual([
      `GET /repos/DrDustinEdwards/novels/contents/${SLUG}/chapters/01-arrival/02-supper.md`,
    ]);
    // The checks ran on what changed outside Carrel, with the book's own habits list.
    expect((await listFindings(testEnv.DB, project)).map((f) => f.excerpt)).toEqual(["Suddenly"]);
  });
});

describe("saving", () => {
  it("PLANT: a Reader cannot autosave or save, and Git hears nothing", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("reader@test.invalid");
    const path = "chapters/01-arrival/01-the-gate.md";
    expect(await refusal(autosave(testEnv.DB, project, viewer, path, { source: "x", baseVersion: null }))).toBe(403);
    expect(await refusal(saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: "x", expectedVersion: null }))).toBe(403);
    expect(gh.requests.filter((r) => r.startsWith("PUT"))).toEqual([]);
  });

  it("PLANT: a path outside the layout is refused before Git is asked", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    for (const path of ["../other-book/book.md", "build/x.md", "chapters/one/two.md", "notes.txt", "chapters/01-a/01-b.md/../../x.md"]) {
      expect(await refusal(saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: "x", expectedVersion: null }))).toBe(404);
    }
    expect(gh.requests).toEqual([]);
  });

  it("commits as the person with a change id and no AI trailer, records authorship, clears the draft", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("editor@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const path = "chapters/01-arrival/01-the-gate.md";
    const file = (await listFiles(testEnv.DB, project)).find((f) => f.path === path)!;
    await autosave(testEnv.DB, project, viewer, path, { source: "draft", baseVersion: file.sha });

    const result = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, {
      source: `${HEADER}Wade opened the old gate slowly.\n`,
      expectedVersion: file.sha,
    });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(gh.commits).toHaveLength(1);
    expect(gh.commits[0]).toMatchObject({ path: `${SLUG}/${path}`, author: { name: "editor", email: "editor@test.invalid" } });
    expect(gh.commits[0]!.message).toBe(`Save ${SLUG}/${path}\n\nCarrel-Change: ${result.changeId}`);
    expect(gh.commits[0]!.message).not.toMatch(/claude|anthropic|co-authored/i);
    expect(await readDraft(testEnv.DB, project, viewer, path)).toBeNull();

    const record = await authorshipRecord(testEnv.DB, project);
    expect(record).toMatchObject([{ id: result.changeId, path, who: "editor", client: null, wordsAdded: 2, wordsRemoved: 0, commit: result.commit }]);
    const report = authorshipReport(project, record, new Date("2026-09-27T00:00:00Z"));
    expect(report).toContain("| editor | 1 | 2 | 0 |");
    expect(report).toContain(`| editor | ${path} | 2 | 0 | ${result.commit.slice(0, 7)} |`);
  });

  it("PLANT: a stale expected version is refused as a conflict, and the draft is kept", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const path = "chapters/01-arrival/01-the-gate.md";
    const opened = (await listFiles(testEnv.DB, project)).find((f) => f.path === path)!.sha;
    await autosave(testEnv.DB, project, viewer, path, { source: "my words", baseVersion: opened });
    await gh.commitElsewhere(`${SLUG}/${path}`, `${HEADER}Someone else's words.\n`);

    const result = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: "my words", expectedVersion: opened });
    expect(result).toMatchObject({ ok: false, reason: "conflict" });
    expect(gh.files.get(`${SLUG}/${path}`)!.source).toBe(`${HEADER}Someone else's words.\n`);
    expect((await readDraft(testEnv.DB, project, viewer, path))?.source).toBe("my words");
    expect(await authorshipRecord(testEnv.DB, project)).toEqual([]);
  });

  it("creates a new scene only where no file exists", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    const path = "chapters/02-letters/01-morning.md";
    const created = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: `${HEADER.replace("2024-04-12", "2024-04-13")}Morning.\n`, expectedVersion: null });
    expect(created.ok).toBe(true);
    const again = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: "overwrite", expectedVersion: null });
    expect(again).toMatchObject({ ok: false, reason: "conflict" });
  });
});

describe("checks on save", () => {
  it("PLANT: a flagged scene still saves; the flags come back and are recorded", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const path = "chapters/01-arrival/03-late.md";
    const source = HEADER.replace("characters: [Wade]", "characters: [Wade, Tobias]").replace("2024-04-12", "2024-04-11") + "Then the phone rang. It's not just a farm, it's a promise.\n";
    const result = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source, expectedVersion: null });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(gh.files.get(`${SLUG}/${path}`)!.source).toBe(source);
    expect(result.findings.map((f) => f.check).sort()).toEqual(["ai-habits", "continuity", "timeline", "world-rules"]);
    expect((await listFindings(testEnv.DB, project, { path })).map((f) => f.check).sort()).toEqual(["ai-habits", "continuity", "timeline", "world-rules"]);
  });

  it("PLANT: the voice check flags another author's passage once shared/voice/ holds Dustin's", async () => {
    const voice = Object.fromEntries(BASELINE.map((text, i) => [`shared/voice/passage-${i + 1}.md`, text]));
    const gh = seedRepo({ ...voice, "shared/voice/README.md": "Put your passages here." });
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const result = await saveBookFile(testEnv.DB, gh.repo, project, viewer, "chapters/01-arrival/03-tea.md", {
      source: HEADER.replace("2024-04-12", "2024-04-13") + PLANT,
      expectedVersion: null,
    });
    expect(result.ok && result.findings.map((f) => f.check)).toEqual(["voice"]);
  });

  it("fixing the text clears the flag; saving a bible entry rechecks every scene", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const path = "chapters/01-arrival/03-late.md";
    const withTobias = HEADER.replace("characters: [Wade]", "characters: [Wade, Tobias]").replace("2024-04-12", "2024-04-13") + "Quiet.\n";
    const saved = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: withTobias, expectedVersion: null });
    expect((await listFindings(testEnv.DB, project, { status: "open" })).map((f) => f.excerpt)).toEqual(["Tobias"]);

    // Adding Tobias to the bible resolves the scene's flag without touching the scene.
    const bible = await saveBookFile(testEnv.DB, gh.repo, project, viewer, "bible/characters/tobias.md", { source: "---\nname: Tobias\n---\n", expectedVersion: null });
    expect(bible.ok && saved.ok).toBe(true);
    expect(await listFindings(testEnv.DB, project)).toEqual([]);
  });

  it("checks a draft without saving or recording anything", async () => {
    const gh = seedRepo();
    const { project } = await as("reader@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const found = await checkDraft(testEnv.DB, project, "chapters/01-arrival/01-the-gate.md", `${HEADER}A tapestry.\n`);
    expect(found.map((f) => f.excerpt)).toEqual(["tapestry"]);
    expect(await listFindings(testEnv.DB, project)).toEqual([]);
    expect(gh.requests.filter((r) => r.startsWith("PUT"))).toEqual([]);
  });
});

describe("dismissing flags and exporting", () => {
  async function flagged() {
    const gh = seedRepo();
    const owner = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, owner.project);
    await saveBookFile(testEnv.DB, gh.repo, owner.project, owner.viewer, "chapters/01-arrival/03-late.md", {
      source: HEADER.replace("2024-04-12", "2024-04-13") + "A tapestry. Another tapestry.\n",
      expectedVersion: null,
    });
    return { gh, owner };
  }

  it("PLANT: export is refused while a flag is open, and to anyone but the Owner", async () => {
    const { owner } = await flagged();
    expect(await exportGate(testEnv.DB, owner.project)).toMatchObject({ ok: false, open: 2 });
    const editor = await as("editor@test.invalid");
    expect(await refusal(exportGate(testEnv.DB, editor.project))).toBe(403);
    expect(await refusal(assembleBook(testEnv.DB, editor.project, editor.viewer))).toBe(403);
  });

  it("PLANT: an Editor cannot dismiss a flag; the Owner can, and a dismissal survives the next save", async () => {
    const { gh, owner } = await flagged();
    const editor = await as("editor@test.invalid");
    const [first, second] = await listFindings(testEnv.DB, owner.project);
    expect(await refusal(dismissFinding(testEnv.DB, editor.project, editor.viewer, first!.id))).toBe(403);

    await dismissFinding(testEnv.DB, owner.project, owner.viewer, first!.id);
    await dismissFinding(testEnv.DB, owner.project, owner.viewer, second!.id);
    expect(await exportGate(testEnv.DB, owner.project)).toEqual({ ok: true });

    // Saving again with the same words keeps both dismissed; a new tapestry is a new flag.
    const path = "chapters/01-arrival/03-late.md";
    const current = gh.files.get(`${SLUG}/${path}`)!;
    await saveBookFile(testEnv.DB, gh.repo, owner.project, owner.viewer, path, { source: `${current.source}A third tapestry.\n`, expectedVersion: current.sha });
    const all = await listFindings(testEnv.DB, owner.project);
    expect(all.map((f) => f.status).sort()).toEqual(["dismissed", "dismissed", "open"]);
  });

  it("a dismissal in another book cannot be reached by id", async () => {
    const { owner } = await flagged();
    const [finding] = await listFindings(testEnv.DB, owner.project);
    await addBook("other-book");
    const other = await requireBookProject(testEnv.DB, owner.viewer, "other-book", "publish");
    expect(await refusal(dismissFinding(testEnv.DB, other, owner.viewer, finding!.id))).toBe(404);
  });

  it("assembles the book in reading order with its title and author from book.md", async () => {
    const gh = seedRepo({ [`${SLUG}/chapters/10-late/01-end.md`]: `${HEADER.replace("2024-04-12", "2024-05-01")}The end.\n` });
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const book = await assembleBook(testEnv.DB, project, viewer);
    expect(book.title).toBe("The Test Book");
    expect(book.author).toBe("Test Author");
    expect(book.chapters.map((c) => [c.title, c.scenes.map((s) => s.body)])).toEqual([
      ["Arrival", ["Wade opened the gate.", "They ate at the kitchen table."]],
      ["Late", ["The end."]],
    ]);
  });
});

describe("word counts for the authorship record", () => {
  it("counts a changed word once each way and a moved word not at all", () => {
    expect(wordDelta("the cat sat", "the dog sat")).toEqual({ added: 1, removed: 1 });
    expect(wordDelta("a b c", "c b a")).toEqual({ added: 0, removed: 0 });
    expect(wordDelta(null, "---\ntitle: x\n---\none two")).toEqual({ added: 2, removed: 0 });
  });
});

