// The media library (stage 3) over site-api v0.2.0's media group. The site is site-api's own handler
// over its reference adapter, whose reference check scans post sources for /media/<id> as
// dustinedwards.info's does. Planted: each role refusal, a delete of a file a post uses (refused with
// the post named), an upload the site would refuse (never sent), and bytes the site API refuses.

import { memoryAdapter } from "@dustinedwards/site-api/testing";
import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { runHealth } from "~/lib/health.server";
import { deleteMedia, listMedia, mediaDetail, mediaLimits, uploadMedia } from "~/lib/media.server";
import { requireSiteProject } from "~/lib/projects.server";
import { figureMarkup } from "~/lib/site-markdown";
import { loader as editorLoader } from "~/routes/editor";
import { action as mediaAction, loader as mediaLoader } from "~/routes/media";
import { action as apiAction, loader as apiLoader } from "~/routes/media.api";

import { appPolicy } from "../workers/csp";
import { addPerson, addProject, resetDb, share } from "./env";
import { connectedEnv, fakeSite, SITE_ORIGIN, viewerFor } from "./site";

const SLUG = "de-info";
const PNG = Uint8Array.from(
  atob("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg=="),
  (c) => c.charCodeAt(0),
);

let site: ReturnType<typeof fakeSite<ReturnType<typeof memoryAdapter>>>;
let env: Env;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  await addPerson("stranger@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, editor, "editor");
  await share(id, reader, "reader");
  site = fakeSite();
  env = connectedEnv();
  vi.stubGlobal("fetch", site.fetch);
});

async function project(email: string, action: Parameters<typeof requireSiteProject>[3] = "read") {
  return requireSiteProject(env.DB, await viewerFor(email), SLUG, action);
}

async function actor(email: string) {
  return { viewer: await viewerFor(email) };
}

function file(bytes: Uint8Array, name = "river.png", type = "image/png") {
  return { name, type, size: bytes.byteLength, bytes: async () => bytes.slice().buffer };
}

async function status(run: () => Promise<unknown>): Promise<number> {
  try {
    await run();
    return 200;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
}

async function contextFor(email: string, e: Env = env) {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env: e, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(email));
  context.set(nonceContext, "n");
  return context;
}

/** A file on the site, uploaded as the site would take it from anyone. */
async function seedFile(name = "river.png") {
  return site.adapter.media!.upload({ bytes: PNG, contentType: "image/png", filename: name, alt: "The river", changeId: "seed" });
}

describe("the library through the site API", () => {
  it("lists, searches and reads a file with its uses, and shows it at the site's own address", async () => {
    const item = await seedFile();
    const reader = await project("reader@test.invalid");
    const list = await listMedia(env, reader, {});
    expect(list.items).toMatchObject([{ id: item.id, url: `/media/${item.id}`, src: `${SITE_ORIGIN}/media/${item.id}`, alt: "The river" }]);
    expect((await listMedia(env, reader, { q: "nothing-like-it" })).items).toEqual([]);
    expect(await mediaDetail(env, reader, item.id)).toMatchObject({ id: item.id, usedBy: [] });
    expect(await mediaDetail(env, reader, "uploads/no-such.png")).toBeNull();
    expect(await mediaLimits(env, reader)).toMatchObject({ types: expect.arrayContaining(["image/png"]) });
  });

  it("uploads as an Editor into the site's own storage", async () => {
    const outcome = await uploadMedia(env, await project("editor@test.invalid"), await actor("editor@test.invalid"), file(PNG), "The river at dusk");
    expect(outcome).toMatchObject({ ok: true, item: { filename: "river.png", alt: "The river at dusk", src: expect.stringMatching(/^https:\/\/site\.test\/media\//) } });
    expect(site.adapter.mediaStore.size).toBe(1);
  });

  it("deletes as the Owner", async () => {
    const item = await seedFile();
    expect(await deleteMedia(env, await project("owner@test.invalid"), await actor("owner@test.invalid"), item.id)).toEqual({ ok: true });
    expect(site.adapter.deleted).toEqual([item.id]);
  });
});

describe("PLANT: roles", () => {
  it("refuses a Reader's upload, and the site hears nothing", async () => {
    const reader = await project("reader@test.invalid");
    expect(await status(async () => uploadMedia(env, reader, await actor("reader@test.invalid"), file(PNG), ""))).toBe(403);
    expect(site.requests.filter((r) => r.startsWith("POST"))).toEqual([]);
  });

  it("refuses an Editor's delete, and the file stays", async () => {
    const item = await seedFile();
    const editor = await project("editor@test.invalid");
    expect(await status(async () => deleteMedia(env, editor, await actor("editor@test.invalid"), item.id))).toBe(403);
    expect(site.adapter.mediaStore.has(item.id)).toBe(true);
    expect(site.requests.filter((r) => r.startsWith("DELETE"))).toEqual([]);
  });

  it("answers 404 to someone the project is not shared with", async () => {
    expect(await status(() => project("stranger@test.invalid"))).toBe(404);
  });

  it("refuses at the routes too: a Reader's upload and an Editor's delete", async () => {
    await seedFile();
    const form = new FormData();
    form.set("file", new File([PNG], "river.png", { type: "image/png" }));
    const upload = new Request(`https://carrel.test/p/${SLUG}/media/api`, { method: "POST", body: form });
    const readerContext = await contextFor("reader@test.invalid");
    expect(await status(() => apiAction({ request: upload, params: { project: SLUG }, context: readerContext } as never))).toBe(403);
    expect(site.requests.filter((r) => r.startsWith("POST"))).toEqual([]);

    const del = new FormData();
    del.set("intent", "delete");
    del.set("id", "uploads/1-river.png");
    del.set("confirm", "delete");
    const request = new Request(`https://carrel.test/p/${SLUG}/media`, { method: "POST", body: del });
    const context = await contextFor("editor@test.invalid");
    expect(await status(() => mediaAction({ request, params: { project: SLUG }, context } as never))).toBe(403);
    expect(site.adapter.mediaStore.size).toBe(1);
  });
});

describe("PLANT: deleting a file a post uses", () => {
  it("is refused by the site's reference check, with the post named, and the file stays", async () => {
    const item = await seedFile();
    await site.adapter.content.saveDraft("river-post", {
      source: `---\ntitle: The river\n---\nIntro.\n\n:::figure{src="${item.url}" alt="The river"}\n:::\n`,
      expectedVersion: null,
      changeId: "c1",
    });
    const owner = await project("owner@test.invalid");
    expect(await mediaDetail(env, owner, item.id)).toMatchObject({ usedBy: [{ id: "river-post", title: "The river", detail: "line 6" }] });

    const outcome = await deleteMedia(env, owner, await actor("owner@test.invalid"), item.id);
    expect(outcome).toMatchObject({ ok: false, usedBy: [{ type: "post", id: "river-post", title: "The river", detail: "line 6" }] });
    expect(!outcome.ok && outcome.message).toContain("The river (line 6)");
    expect(site.adapter.mediaStore.has(item.id)).toBe(true);
    expect(site.adapter.deleted).toEqual([]);
  });

  it("asks before it deletes, then shows the refusal on the page", async () => {
    const item = await seedFile();
    await site.adapter.content.saveDraft("river-post", { source: `# The river\n\n![](${item.url})\n`, expectedVersion: null, changeId: "c1" });
    const post = async (fields: Record<string, string>) => {
      const form = new FormData();
      for (const [k, v] of Object.entries(fields)) form.set(k, v);
      const request = new Request(`https://carrel.test/p/${SLUG}/media`, { method: "POST", body: form });
      return mediaAction({ request, params: { project: SLUG }, context: await contextFor("owner@test.invalid") } as never);
    };
    expect(await post({ intent: "delete", id: item.id })).toEqual({ intent: "delete", needsConfirm: true, id: item.id });
    expect(site.requests.filter((r) => r.startsWith("DELETE"))).toEqual([]);
    expect(await post({ intent: "delete", id: item.id, confirm: "delete" })).toMatchObject({
      intent: "delete",
      ok: false,
      usedBy: [{ id: "river-post", title: "The river" }],
    });
    expect(site.adapter.mediaStore.has(item.id)).toBe(true);
  });
});

describe("PLANT: an upload the site does not accept", () => {
  it("refuses a type the site did not declare before sending anything", async () => {
    const outcome = await uploadMedia(env, await project("editor@test.invalid"), await actor("editor@test.invalid"), file(new TextEncoder().encode("<script>x</script>"), "page.html", "text/html"), "");
    expect(outcome).toMatchObject({ ok: false, message: expect.stringContaining("this site accepts") });
    expect(site.requests.filter((r) => r.startsWith("POST"))).toEqual([]);
  });

  it("refuses a file over the site's limit before sending anything", async () => {
    site = fakeSite(memoryAdapter({ media: { maxBytes: 64, types: ["image/png"] } }));
    vi.stubGlobal("fetch", site.fetch);
    const big = new Uint8Array(65);
    big.set(PNG.subarray(0, 8));
    const outcome = await uploadMedia(env, await project("editor@test.invalid"), await actor("editor@test.invalid"), file(big), "");
    expect(outcome).toMatchObject({ ok: false, message: expect.stringContaining("accepts files up to") });
    expect(site.requests.filter((r) => r.startsWith("POST"))).toEqual([]);
    expect(site.adapter.mediaStore.size).toBe(0);
  });

  it("shows the site API's refusal of bytes that are not their type, and stores nothing", async () => {
    const outcome = await uploadMedia(env, await project("editor@test.invalid"), await actor("editor@test.invalid"), file(new TextEncoder().encode("not a png at all"), "fake.png"), "");
    expect(outcome).toMatchObject({ ok: false, message: expect.stringContaining("The site refused fake.png") });
    expect(site.adapter.mediaStore.size).toBe(0);
  });
});

describe("a site with no media library", () => {
  beforeEach(() => {
    site = fakeSite(memoryAdapter({ media: false }));
    vi.stubGlobal("fetch", site.fetch);
  });

  it("says so on the page, and the editor gets no image tools", async () => {
    const data = (await mediaLoader({ request: new Request(`https://carrel.test/p/${SLUG}/media`), params: { project: SLUG }, context: await contextFor("owner@test.invalid") } as never)) as { unavailable: string | null };
    expect(data.unavailable).toBe("This site has no media library yet.");
    await site.adapter.content.saveDraft("post-one", { source: "# One\n", expectedVersion: null, changeId: "s" });
    const editor = (await editorLoader({ params: { project: SLUG, item: "post-one" }, context: await contextFor("owner@test.invalid") } as never)) as { media: unknown };
    expect(editor.media).toBeNull();
  });
});

describe("the editor's image tools", () => {
  it("are given to an Editor with the site's accepted types, and never to a Reader", async () => {
    await site.adapter.content.saveDraft("post-one", { source: "# One\n", expectedVersion: null, changeId: "s" });
    const load = async (email: string) =>
      (await editorLoader({ params: { project: SLUG, item: "post-one" }, context: await contextFor(email) } as never)) as { media: { endpoint: string; accept: string } | null };
    expect((await load("editor@test.invalid")).media).toEqual({ endpoint: `/p/${SLUG}/media/api`, accept: expect.stringContaining("image/png") });
    expect((await load("reader@test.invalid")).media).toBeNull();
  });

  it("uploads through the endpoint and answers the site's address and where to show it", async () => {
    const form = new FormData();
    form.set("file", new File([PNG], "river.png", { type: "image/png" }));
    const request = new Request(`https://carrel.test/p/${SLUG}/media/api`, { method: "POST", body: form });
    const response = (await apiAction({ request, params: { project: SLUG }, context: await contextFor("editor@test.invalid") } as never)) as Response;
    expect(response.status).toBe(201);
    const body = (await response.json()) as { url: string; src: string };
    expect(body.url).toMatch(/^\/media\/uploads\//);
    expect(body.src).toBe(`${SITE_ORIGIN}${body.url}`);
  });

  it("lists for the picker, and says why when the site cannot be reached", async () => {
    await seedFile();
    const list = (await apiLoader({ request: new Request(`https://carrel.test/p/${SLUG}/media/api?q=river`), params: { project: SLUG }, context: await contextFor("reader@test.invalid") } as never)) as Response;
    expect(((await list.json()) as { items: unknown[] }).items).toHaveLength(1);
    const offline = { ...env, SITE_DUSTINEDWARDS_KEY: "" };
    const answer = (await apiLoader({ request: new Request(`https://carrel.test/p/${SLUG}/media/api`), params: { project: SLUG }, context: await contextFor("reader@test.invalid", offline) } as never)) as Response;
    expect(await answer.json()).toMatchObject({ items: [], error: expect.stringContaining("not connected") });
  });

  it("inserts the site's own figure, with the alt text escaped", () => {
    expect(figureMarkup("dustinedwards", "/media/a.png", ' The "river" ')).toBe(':::figure{src="/media/a.png" alt="The &quot;river&quot;"}\n:::');
    expect(figureMarkup("some-other-site", "/media/a.png", "A [river]")).toBe("![A river](/media/a.png)");
  });
});

describe("the image policy", () => {
  it("loads images from the configured sites, and drops anything that is not a plain https origin", () => {
    const policy = appPolicy("n", ["https://site.test", "https://evil.test; script-src *", "http://plain.test"]);
    expect(policy).toContain("img-src 'self' data: https://site.test;");
    expect(policy).not.toContain("evil.test");
    expect(policy).not.toContain("plain.test");
  });
});

describe("health", () => {
  it("runs the media conformance against a site with media, and never stores or deletes a file", async () => {
    const existing = await seedFile();
    const box = { sent: [] as unknown[] };
    const EMAIL = { send: async (m: unknown) => (box.sent.push(m), { messageId: "m" }) } as unknown as SendEmail;
    const fetcher = (async (input: RequestInfo | URL, init?: RequestInit) => {
      const url = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;
      return url.includes("cloudflareaccess") ? Response.json({ keys: [{ kid: "k" }] }) : site.fetch(url, init);
    }) as unknown as Parameters<typeof runHealth>[1];
    const { results } = await runHealth({ ...env, EMAIL }, fetcher);
    expect(results.find((r) => r.name === "site-dustinedwards")).toMatchObject({ ok: true });
    expect(site.requests).toEqual(expect.arrayContaining(["GET /api/carrel/v1/media", "DELETE /api/carrel/v1/media/carrel-conformance-probe%2Fno-such-file.png", "POST /api/carrel/v1/media"]));
    expect([...site.adapter.mediaStore.keys()]).toEqual([existing.id]);
    expect(site.adapter.deleted).toEqual([]);
  });
});

test/mcp.test.ts.source:
// The MCP endpoint and its tools, as an AI client meets them: the protocol in both eras, the tools
// over posts, and the planted refusals from design decision 2 (a shared user's session publishing, a
// reviewer publishing, an Owner's publish with an open flag). The site is site-api's own handler over
// its reference adapter; the email binding is a mailbox the tests read. The session is what the door
// hands over from the OAuth grant: the person and the client, credited by the client's name.

import { beforeEach, describe, expect, it } from "vitest";

import { autosave, readDraft } from "~/lib/content.server";
import { runHealth } from "~/lib/health.server";
import { requireSiteProject } from "~/lib/projects.server";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectAs, legacyRequest, LEGACY, MCP_HOST, MCP_URL, modernRequest, readMessage } from "./mcp-client";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
const CARREL = "https://carrel.test";

type Sent = { from: string; to: string; subject: string; text: string };

function mailbox(fail = false) {
  const sent: Sent[] = [];
  const EMAIL = {
    async send(message: Sent) {
      if (fail) throw new Error("send failed");
      sent.push(message);
      return { messageId: `m${sent.length}` };
    },
  } as unknown as SendEmail;
  return { sent, EMAIL };
}

let site: ReturnType<typeof fakeSite>;
let box: ReturnType<typeof mailbox>;
let env: Env;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  const reviewer = await addPerson("reviewer@test.invalid", { reviewer: true });
  await addPerson("stranger@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, editor, "editor");
  await share(id, reader, "reader");
  await share(id, reviewer, "reader");
  site = fakeSite();
  box = mailbox();
  env = { ...connectedEnv(), EMAIL: box.EMAIL };
});

async function connect(email: string, client = "Claude", e: Env = env) {
  return connectAs(email, client, { env: e, deps: { fetcher: site.fetch, carrelOrigin: CARREL } });
}

/** A post the Owner saved on the site through the buttons' own function, returned with its version. */
async function seedPost(status: "draft" | "published" = "draft") {
  const saved = await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Post one\n---\nDustin's words.\n", expectedVersion: null, changeId: "seed" });
  if (status === "draft") return saved.version;
  return (await site.adapter.content.publish("post-one", { expectedVersion: saved.version, changeId: "seed-publish" })).version;
}

describe("the protocol", () => {
  it("lists the tools in the 2026-07-28 era, each carrying the rule", async () => {
    const tools = await (await connect("owner@test.invalid")).list();
    expect(tools.map((t) => t.name)).toEqual(["list_projects", "search_items", "read_item", "save_draft", "preview", "get_checks", "add_finding", "publish", "list_book_files", "read_book_file", "check_book_text", "save_book_draft", "add_book_finding", "draft_social_post"]);
    for (const tool of tools) expect(tool.description).toContain("AI never rewrites Dustin's prose unasked.");
  });

  it("answers a 2025-era client through the legacy shim: initialize, then calls with no session", async () => {
    const ai = await connect("reader@test.invalid");
    const init = await readMessage(
      await ai.send(legacyRequest({ jsonrpc: "2.0", id: 1, method: "initialize", params: { protocolVersion: LEGACY, capabilities: {}, clientInfo: { name: "Claude Code", version: "2.1" } } })),
    );
    expect(init.result).toMatchObject({ protocolVersion: LEGACY, serverInfo: { name: "carrel" }, capabilities: { tools: {} } });
    const legacy = await connectAs("reader@test.invalid", "Claude", { env, deps: { fetcher: site.fetch, carrelOrigin: CARREL }, era: "legacy" });
    expect((await legacy.list()).length).toBe(14);
    expect((await legacy.call("list_projects")).structuredContent).toMatchObject({ projects: [{ slug: SLUG, role: "reader" }] });
  });

  it("answers an unknown protocol version at initialize with one it speaks", async () => {
    const ai = await connect("owner@test.invalid");
    const init = await readMessage(await ai.send(legacyRequest({ jsonrpc: "2.0", id: 1, method: "initialize", params: { protocolVersion: "1999-01-01", capabilities: {}, clientInfo: { name: "x", version: "1" } } })));
    expect(["2025-11-25", "2025-06-18", "2025-03-26"]).toContain(init.result?.protocolVersion);
  });

  it("PLANT: a page elsewhere cannot drive the tools, a rebinding host is refused, and GET, DELETE, 2026-era batches and bad JSON are refused", async () => {
    const ai = await connect("owner@test.invalid");
    expect((await ai.send(modernRequest(2, "tools/list", {}, { Origin: "https://evil.example" }))).status).toBe(403);
    expect((await ai.send(modernRequest(2, "tools/list", {}, { Host: "evil.example" }))).status).toBe(403);
    expect((await ai.send(new Request(MCP_URL, { headers: { Host: MCP_HOST, Accept: "text/event-stream" } }))).status).toBe(405);
    expect((await ai.send(new Request(MCP_URL, { method: "DELETE", headers: { Host: MCP_HOST } }))).status).toBe(405);
    const one = modernRequest(1, "tools/list");
    const body = [JSON.parse(await one.clone().text()), JSON.parse(await one.clone().text())];
    const batch = await ai.send(new Request(one, { body: JSON.stringify(body) }));
    // Refused in the design-center era. The legacy shim answers 2025-era batches as that era allowed;
    // each message in one still runs as this same session, so a batch widens nothing.
    expect(batch.status).toBe(400);
    const bad = new Request(MCP_URL, { method: "POST", body: "{not json", headers: { Host: MCP_HOST, "Content-Type": "application/json", Accept: "application/json, text/event-stream" } });
    expect((await ai.send(bad)).status).toBe(400);
  });
});

describe("reading, drafting, flagging", () => {
  it("lists projects, searches and reads posts through the buttons' own functions", async () => {
    await seedPost();
    const ai = await connect("reader@test.invalid");
    expect((await ai.call("list_projects")).structuredContent).toMatchObject({ projects: [{ slug: SLUG, role: "reader" }] });
    const read = await ai.call("read_item", { project: SLUG, item: "post-one" });
    expect(read.isError).toBeUndefined();
    expect(read.structuredContent).toMatchObject({ site: { id: "post-one", title: "Post one" }, dustinsDraft: null, aiDrafts: [], flags: [] });
  });

  it("PLANT: a stranger's session reads nothing", async () => {
    const ai = await connect("stranger@test.invalid");
    const result = await ai.call("read_item", { project: SLUG, item: "post-one" });
    expect(result).toMatchObject({ isError: true, content: [{ text: "Not found, or not shared with this person." }] });
  });

  it("saves an AI draft beside Dustin's, never over his draft or the site's text", async () => {
    const version = await seedPost();
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireSiteProject(testEnv.DB, owner, SLUG, "read");
    await autosave(testEnv.DB, project, owner, "post-one", { source: "Dustin's working draft.", baseVersion: version });

    const ai = await connect("owner@test.invalid");
    const saved = await ai.call("save_draft", { project: SLUG, item: "post-one", source: "An AI rewrite.", note: "Tightened the opening." });
    expect(saved.structuredContent).toMatchObject({ saved: true, basedOnVersion: version });
    expect((await readDraft(testEnv.DB, project, owner, "post-one"))?.source).toBe("Dustin's working draft.");
    expect((await site.adapter.content.get("post-one"))?.source).toBe("---\ntitle: Post one\n---\nDustin's words.\n");
    expect(site.requests.filter((r) => !r.startsWith("GET"))).toEqual([]);
    const read = await ai.call("read_item", { project: SLUG, item: "post-one" });
    expect(read.structuredContent).toMatchObject({ aiDrafts: [{ client: "Claude", note: "Tightened the opening." }] });
  });

  it("PLANT: a Reader's session and a reviewer's cannot save a draft", async () => {
    await seedPost();
    expect(await (await connect("reader@test.invalid")).call("save_draft", { project: SLUG, item: "post-one", source: "x" })).toMatchObject({
      isError: true,
      content: [{ text: "You may not write drafts on this project." }],
    });
    expect(await (await connect("reviewer@test.invalid")).call("save_draft", { project: SLUG, item: "post-one", source: "x" })).toMatchObject({
      isError: true,
      content: [{ text: "A reviewer flags; it does not write text. Use add_finding." }],
    });
  });

  it("lets a reviewer flag, once per flag, credited to its client", async () => {
    await seedPost();
    const reviewer = await connect("reviewer@test.invalid", "Grok Build");
    const args = { project: SLUG, item: "post-one", message: "This number has no source.", excerpt: "Dustin's words." };
    expect((await reviewer.call("add_finding", args)).structuredContent).toMatchObject({ flagged: true, alreadyFlagged: false });
    expect((await reviewer.call("add_finding", args)).structuredContent).toMatchObject({ alreadyFlagged: true });
    const checks = await (await connect("owner@test.invalid")).call("get_checks", { project: SLUG, item: "post-one" });
    expect(checks.structuredContent).toMatchObject({ open: 1, flags: [{ check: "review", message: "This number has no source. (from Grok Build)" }] });
  });

  it("previews through the site's own renderer", async () => {
    await seedPost();
    const result = await (await connect("reader@test.invalid")).call("preview", { project: SLUG, item: "post-one", source: "---\ntitle: T\n---\nHello." });
    expect(result.isError).toBeUndefined();
    expect(String(result.structuredContent?.html)).toContain("Hello.");
  });
});

describe("publish by instruction (decision 2)", () => {
  it("PLANT: a shared user's session publishing is refused, and the site and inbox hear nothing", async () => {
    const version = await seedPost();
    const result = await (await connect("editor@test.invalid")).call("publish", { project: SLUG, item: "post-one", expected_version: version });
    expect(result).toMatchObject({ isError: true, content: [{ text: "Only the Owner's own sessions may publish." }] });
    expect((await site.adapter.content.get("post-one"))?.status).toBe("draft");
    expect(site.requests.filter((r) => !r.startsWith("GET"))).toEqual([]);
    expect(box.sent).toEqual([]);
  });

  it("PLANT: a reviewer publishing is refused", async () => {
    const version = await seedPost();
    const result = await (await connect("reviewer@test.invalid")).call("publish", { project: SLUG, item: "post-one", expected_version: version });
    expect(result).toMatchObject({ isError: true, content: [{ text: "A reviewer never publishes." }] });
    expect((await site.adapter.content.get("post-one"))?.status).toBe("draft");
  });

  it("PLANT: the Owner's AI publish with an open flag is refused, naming the flag", async () => {
    const version = await seedPost();
    await (await connect("reviewer@test.invalid", "Grok Build")).call("add_finding", { project: SLUG, item: "post-one", message: "Unsourced claim." });
    const result = await (await connect("owner@test.invalid")).call("publish", { project: SLUG, item: "post-one", expected_version: version });
    expect(result.isError).toBe(true);
    expect(result.content[0]!.text).toBe(
      "Publish is refused while 1 flag is open on this post: Unsourced claim. (from Grok Build) Dustin fixes the text or dismisses each flag in Carrel first.",
    );
    expect((await site.adapter.content.get("post-one"))?.status).toBe("draft");
    expect(box.sent).toEqual([]);
  });

  it("the Owner's AI publish with clean checks publishes, credits the client, and emails Dustin an unpublish link", async () => {
    const version = await seedPost();
    const result = await (await connect("owner@test.invalid", "Claude")).call("publish", { project: SLUG, item: "post-one", expected_version: version });
    expect(result.structuredContent).toMatchObject({ published: true, dustinEmailed: true });
    expect((await site.adapter.content.get("post-one"))?.status).toBe("published");

    const change = await testEnv.DB.prepare("SELECT action, client FROM changes WHERE item_id = 'post-one'").first();
    expect(change).toEqual({ action: "publish", client: "Claude" });
    const record = await testEnv.DB.prepare("SELECT client, emailed_at, email_error FROM ai_publications").first<{ client: string; emailed_at: string | null; email_error: string | null }>();
    expect(record).toMatchObject({ client: "Claude", email_error: null });
    expect(record!.emailed_at).not.toBeNull();

    expect(box.sent).toHaveLength(1);
    expect(box.sent[0]).toMatchObject({ to: "owner@test.invalid", subject: 'Carrel: Claude published "Post one"' });
    expect(box.sent[0]!.text).toContain("Published by Claude on Dustin's instruction.");
    expect(box.sent[0]!.text).toContain(`Unpublish it: ${CARREL}/p/${SLUG}/e/post-one/unpublish`);
  });

  it("PLANT: publish sends no text, so an AI draft can never be what goes live", async () => {
    const version = await seedPost();
    const ai = await connect("owner@test.invalid");
    await ai.call("save_draft", { project: SLUG, item: "post-one", source: "---\ntitle: Post one\n---\nAI words.\n" });
    await ai.call("publish", { project: SLUG, item: "post-one", expected_version: version });
    expect((await site.adapter.content.get("post-one"))?.source).toBe("---\ntitle: Post one\n---\nDustin's words.\n");
  });

  it("PLANT: a stale expected version is refused by the site", async () => {
    await seedPost();
    const result = await (await connect("owner@test.invalid")).call("publish", { project: SLUG, item: "post-one", expected_version: "stale" });
    expect(result.isError).toBe(true);
    expect((await site.adapter.content.get("post-one"))?.status).toBe("draft");
  });

  it("keeps the publish when the email fails, records why, and the health check reports it", async () => {
    const version = await seedPost();
    const failing = mailbox(true);
    const e = { ...env, EMAIL: failing.EMAIL };
    const result = await (await connect("owner@test.invalid", "Claude", e)).call("publish", { project: SLUG, item: "post-one", expected_version: version });
    expect(result.structuredContent).toMatchObject({ published: true, dustinEmailed: false });

    const health = mailbox();
    const { results } = await runHealth({ ...testEnv, EMAIL: health.EMAIL }, async () => Response.json({ keys: [{ kid: "k" }] }));
    expect(results.find((r) => r.name === "ai-publish-email")).toMatchObject({ ok: false, detail: "1 AI publish was not emailed: post-one by Claude (send failed)." });
  });
});

